                                    imageRendering: 'auto',
                                    backgroundColor: 'transparent'
                                  }}
                                />
                              ) : (
                                <div className="text-white text-2xl font-semibold">
                                  {getPlayerInitials(`${player.firstName} ${player.lastName}`)}
