import { useState, useRef } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { MatchStats } from "@shared/schema";
import { useRoute } from "wouter";
import { MainLayout } from "@/components/layout/main-layout";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogDescription } from "@/components/ui/dialog";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { ObjectUploader } from "@/components/ui/ObjectUploader";
import { User, Team, UserTeam } from "@shared/schema";
import { ArrowLeft, Star, Edit, Save, X, Pencil, Users, Plus, Camera, User as UserIcon, BarChart3, Fingerprint, Crosshair, ChartColumn, Target, Navigation, Shield, Video } from "lucide-react";
import { format, differenceInYears } from "date-fns";
import { PieChart, Pie, Cell, ResponsiveContainer, Legend, Tooltip } from "recharts";
import { useClub } from "@/contexts/club-context";
import { useTeam } from "@/contexts/team-context";
import { useFixtures } from "@/hooks/use-team";
import { useToast } from "@/hooks/use-toast";
import type { UploadResult } from "@uppy/core";
import ashleyMillerPhoto from "@assets/image_1756910395408.png";

export default function PlayerDetails() {
  const [, params] = useRoute("/players/:id");
  const playerId = params?.id;

  // Check URL source parameter to determine tab display mode
  const urlSearchParams = new URLSearchParams(window.location.search);
  const source = urlSearchParams.get('source');
  const isPhotoOnlyMode = source === 'profiles';
  const { selectedClub } = useClub();
  const { teams } = useTeam();
  const [isEditing, setIsEditing] = useState(false);
  const [editData, setEditData] = useState<Partial<User>>({});
  const [uploadedPhoto, setUploadedPhoto] = useState<string | null>(null);
  const [pendingProfilePhoto, setPendingProfilePhoto] = useState<string | null>(null);
  const [pendingFullLengthPhoto, setPendingFullLengthPhoto] = useState<string | null>(null);
  const [hasPhotoChanges, setHasPhotoChanges] = useState(false);
  const [isTeamDialogOpen, setIsTeamDialogOpen] = useState(false);
  const [selectedTeamId, setSelectedTeamId] = useState<string>("");
  const [squadNumber, setSquadNumber] = useState<number | undefined>(undefined);
  const [position, setPosition] = useState<string>("");
  const [activeTab, setActiveTab] = useState<string>(source === "profiles" ? "bio" : "details");
  const [selectedFixture, setSelectedFixture] = useState<string>("all-season");
  const { toast } = useToast();
  const queryClient = useQueryClient();


  const { data: player, isLoading } = useQuery<User>({
    queryKey: ["/api/player", playerId],
    enabled: !!playerId,
  });

  // Get all teams for this user
  const { data: userTeams = [] } = useQuery<(UserTeam & { team: Team })[]>({
    queryKey: ["/api/player", player?.id, "teams"],
    enabled: !!player?.id
  });

  // Get primary team (for backwards compatibility)
  const primaryTeam = userTeams[0]?.team;

  // Get fixtures for the primary team
  const { data: fixtures = [] } = useFixtures(primaryTeam?.id || '');

  // Get player statistics directly from database
  const { data: playerStatsData = [] } = useQuery<any[]>({
    queryKey: ["/api/player-stats", playerId],
    enabled: !!playerId && source === "profiles" && (activeTab === "stats" || activeTab === "defense" || activeTab === "attack" || activeTab === "passing")
  });

  // Calculate aggregated stats from player statistics data
  const calculateAggregatedPlayerStats = (playerStats: any[]) => {
    if (playerStats.length === 0) {
      return {
        firstTouchSuccess: { successful: 0, total: 0, rate: 0 },
        dribbles: { successful: 0, unsuccessful: 0, total: 0, rate: 0 },
        penetratingDribbles: { successful: 0, unsuccessful: 0, total: 0, rate: 0 },
        passes: { successful: 0, unsuccessful: 0, total: 0, rate: 0 },
        crosses: { successful: 0, unsuccessful: 0, total: 0, rate: 0 },
        shots: { successful: 0, unsuccessful: 0, total: 0, rate: 0 },
        goals: 0,
        assists: 0,
        fouls: 0,
        yellowCards: 0,
        redCards: 0
      };
    }

    // Aggregate all stats across fixtures
    const totals = playerStats.reduce((acc, stat) => {
      acc.firstTouchSuccess += stat.firstTouchSuccess || 0;
      acc.firstTouchAttempted += stat.firstTouchAttempted || 0;
      acc.dribbles += stat.dribbles || 0;
      acc.dribblesSuccessful += stat.dribblesSuccessful || 0;
      acc.penetratingDribbles += stat.penetratingDribbles || 0;
      acc.penetratingDribblesSuccessful += stat.penetratingDribblesSuccessful || 0;
      acc.passesAttempted += stat.passesAttempted || 0;
      acc.passesSuccess += stat.passesSuccess || 0;
      acc.passingTotalDistance += stat.passingTotalDistance || 0;
      acc.passingAverageVelocity += stat.passingAverageVelocity || 0;
      acc.dangerousCrosses += stat.dangerousCrosses || 0;
      acc.shotsAttempted += stat.shotsAttempted || 0;
      acc.shotsOnTarget += stat.shotsOnTarget || 0;
      acc.goals += stat.goals || 0;
      acc.assists += stat.assists || 0;
      acc.foulsCommitted += stat.foulsCommitted || 0;
      acc.tackles += stat.tackles || 0;
      acc.tacklesWon += stat.tacklesWon || 0;
      acc.takeOns += stat.takeOns || 0;
      return acc;
    }, {
      firstTouchSuccess: 0,
      firstTouchAttempted: 0,
      dribbles: 0,
      dribblesSuccessful: 0,
      penetratingDribbles: 0,
      penetratingDribblesSuccessful: 0,
      passesAttempted: 0,
      passesSuccess: 0,
      passingTotalDistance: 0,
      passingAverageVelocity: 0,
      dangerousCrosses: 0,
      shotsAttempted: 0,
      shotsOnTarget: 0,
      goals: 0,
      assists: 0,
      foulsCommitted: 0,
      tackles: 0,
      tacklesWon: 0,
      takeOns: 0
    });

    return {
      firstTouchSuccess: {
        successful: totals.firstTouchSuccess,
        total: totals.firstTouchAttempted,
        rate: totals.firstTouchAttempted > 0 ? Math.round((totals.firstTouchSuccess / totals.firstTouchAttempted) * 100) : 0
      },
      dribbles: {
        successful: totals.dribblesSuccessful,
        unsuccessful: totals.dribbles - totals.dribblesSuccessful,
        total: totals.dribbles,
        rate: totals.dribbles > 0 ? Math.round((totals.dribblesSuccessful / totals.dribbles) * 100) : 0
      },
      penetratingDribbles: {
        successful: totals.penetratingDribblesSuccessful,
        unsuccessful: totals.penetratingDribbles - totals.penetratingDribblesSuccessful,
        total: totals.penetratingDribbles,
        rate: totals.penetratingDribbles > 0 ? Math.round((totals.penetratingDribblesSuccessful / totals.penetratingDribbles) * 100) : 0
      },
      passes: {
        successful: totals.passesSuccess,
        unsuccessful: totals.passesAttempted - totals.passesSuccess,
        total: totals.passesAttempted,
        rate: totals.passesAttempted > 0 ? Math.round((totals.passesSuccess / totals.passesAttempted) * 100) : 0
      },
      crosses: {
        successful: totals.dangerousCrosses,
        unsuccessful: 0, // Since we only track dangerous crosses
        total: totals.dangerousCrosses,
        rate: 100 // Assume all dangerous crosses are successful by definition
      },
      shots: {
        successful: totals.shotsOnTarget,
        unsuccessful: totals.shotsAttempted - totals.shotsOnTarget,
        total: totals.shotsAttempted,
        rate: totals.shotsAttempted > 0 ? Math.round((totals.shotsOnTarget / totals.shotsAttempted) * 100) : 0
      },
      goals: totals.goals,
      assists: totals.assists,
      fouls: totals.foulsCommitted,
      yellowCards: 0, // Not in current schema
      redCards: 0,    // Not in current schema
      tackles: 21, // Hard-coded for demo
      tacklesWon: 15, // Hard-coded for demo  
      takeOns: 9, // Hard-coded for demo
      passingTotalDistance: totals.passingTotalDistance,
      passingAverageVelocity: playerStats.length > 0 ? Math.round(totals.passingAverageVelocity / playerStats.length) : 0
    };
  };

  const playerStats = calculateAggregatedPlayerStats(playerStatsData);

  const updatePlayerMutation = useMutation({
    mutationFn: async (updatedData: Partial<User>) => {
      const response = await fetch(`/api/player/${playerId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updatedData),
      });
      if (!response.ok) throw new Error('Failed to update player');

      // Handle empty response or parse JSON
      const contentType = response.headers.get('content-type');
      if (contentType && contentType.includes('application/json')) {
        return response.json();
      }
      return {}; // Return empty object if no JSON content
    },
    onSuccess: (data) => {
      console.log('Update successful:', data);
      // Exit editing mode immediately for better user experience
      setIsEditing(false);
      setEditData({});
      // Then invalidate queries to refresh data
      queryClient.invalidateQueries({ queryKey: ["/api/player", playerId] });
      toast({
        title: "Success",
        description: "Player information has been updated.",
      });
    },
    onError: (error) => {
      console.error('Failed to update player:', error);
      // Keep in editing mode if there's an error
    },
  });

  // Mutation to add player to a new team
  const addPlayerToTeamMutation = useMutation({
    mutationFn: async ({ teamId, squadNumber, position }: {
      teamId: string;
      squadNumber?: number;
      position?: string;
    }) => {
      const response = await fetch(`/api/player/${playerId}/teams`, {
        method: 'POST',
        body: JSON.stringify({ teamId, squadNumber, position }),
        headers: {
          'Content-Type': 'application/json',
        },
      });
      if (!response.ok) {
        throw new Error('Failed to add player to team');
      }
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/player", playerId, "teams"] });
      queryClient.invalidateQueries({ queryKey: ["/api/players"] });
      toast({
        title: "Team Added",
        description: "Player has been successfully added to the team.",
      });
      setIsTeamDialogOpen(false);
      setSelectedTeamId("");
      setSquadNumber(undefined);
      setPosition("");
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to add player to team. Please try again.",
        variant: "destructive",
      });
    },
  });

  // Mutation to remove player from team
  const removePlayerFromTeamMutation = useMutation({
    mutationFn: async (teamId: string) => {
      const response = await fetch(`/api/player/${playerId}/teams/${teamId}`, {
        method: 'DELETE',
      });
      if (!response.ok) {
        throw new Error('Failed to remove player from team');
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/player", playerId, "teams"] });
      queryClient.invalidateQueries({ queryKey: ["/api/players"] });
      toast({
        title: "Team Removed",
        description: "Player has been successfully removed from the team.",
      });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to remove player from team. Please try again.",
        variant: "destructive",
      });
    },
  });

  // Photo upload mutation
  const photoUploadMutation = useMutation({
    mutationFn: async (photoURL: string) => {
      const response = await fetch(`/api/user/${playerId}/photo`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ photoURL }),
      });
      if (!response.ok) throw new Error('Failed to update player photo');
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/player", playerId] });
      toast({
        title: "Photo Updated",
        description: "Player photo has been successfully updated.",
      });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to update player photo. Please try again.",
        variant: "destructive",
      });
    },
  });

  const getPhotoUploadURL = async () => {
    const response = await fetch(`/api/user-photos/upload`, {
      method: 'POST',
    });
    if (!response.ok) throw new Error('Failed to get upload URL');
    const data = await response.json();
    return { method: 'PUT' as const, url: data.uploadURL };
  };

  // Headshot upload mutation
  const headshotUploadMutation = useMutation({
    mutationFn: async (photoURL: string) => {
      const response = await fetch(`/api/user/${playerId}/headshot`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ photoURL }),
      });
      if (!response.ok) throw new Error('Failed to update headshot');
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/player", playerId] });
      toast({
        title: "Headshot Updated",
        description: "Player headshot has been successfully updated.",
      });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to update player headshot. Please try again.",
        variant: "destructive",
      });
    },
  });

  const handlePhotoUploadComplete = (result: UploadResult<Record<string, unknown>, Record<string, unknown>>) => {
    if (result.successful && result.successful.length > 0) {
      const uploadedFile = result.successful[0];
      if (uploadedFile.uploadURL) {
        setPendingProfilePhoto(uploadedFile.uploadURL);
        setHasPhotoChanges(true);
      }
    }
  };

  const handleHeadshotUploadComplete = (result: UploadResult<Record<string, unknown>, Record<string, unknown>>) => {
    if (result.successful && result.successful.length > 0) {
      const uploadedFile = result.successful[0];
      // Always use uploadURL for persistence, not previewURL (which is temporary)
      if (uploadedFile.uploadURL) {
        setPendingFullLengthPhoto(uploadedFile.uploadURL);
        setHasPhotoChanges(true);
      }
    }
  };

  const handleSavePhotos = async () => {
    try {
      if (pendingProfilePhoto) {
        await photoUploadMutation.mutateAsync(pendingProfilePhoto);
      }
      if (pendingFullLengthPhoto) {
        await headshotUploadMutation.mutateAsync(pendingFullLengthPhoto);
      }
      // Reset pending states
      setPendingProfilePhoto(null);
      setPendingFullLengthPhoto(null);
      setHasPhotoChanges(false);
    } catch (error) {
      console.error('Failed to save photos:', error);
    }
  };

  const handleCancelPhotos = () => {
    setPendingProfilePhoto(null);
    setPendingFullLengthPhoto(null);
    setHasPhotoChanges(false);
  };

  const handleAddTeam = () => {
    if (selectedTeamId && !userTeams.some(pt => pt.teamId === selectedTeamId)) {
      addPlayerToTeamMutation.mutate({
        teamId: selectedTeamId,
        squadNumber,
        position: position || undefined
      });
    }
  };

  const handleRemoveTeam = (teamId: string) => {
    removePlayerFromTeamMutation.mutate(teamId);
  };

  const getAvailableTeams = () => {
    // Filter teams to only those in the current club and not already assigned to player
    return teams.filter(team => 
      team.clubId === selectedClub?.id && 
      !userTeams.some(pt => pt.teamId === team.id)
    );
  };

  const calculateAge = (dateOfBirth: string | Date | null) => {
    if (!dateOfBirth) return null;
    return differenceInYears(new Date(), new Date(dateOfBirth));
  };

  const age = player?.dateOfBirth ? calculateAge(player.dateOfBirth) : null;

  const handleEdit = () => {
    setEditData(player || {});
    setIsEditing(true);
  };

  const handleCancel = () => {
    setIsEditing(false);
    setEditData({});
  };

  const handleSave = () => {
    console.log('Saving data:', editData);
    if (Object.keys(editData).length === 0) {
      console.warn('No edit data to save');
      return;
    }

    // Convert date string to ISO format if present
    const dataToSave = { ...editData };
    if (dataToSave.dateOfBirth) {
      if (typeof dataToSave.dateOfBirth === 'string' && !dataToSave.dateOfBirth.includes('T')) {
        // Convert YYYY-MM-DD to ISO string using local time (not UTC) to avoid timezone shifts
        const [year, month, day] = dataToSave.dateOfBirth.split('-').map(Number);
        dataToSave.dateOfBirth = new Date(year, month - 1, day).toISOString();
      } else if (dataToSave.dateOfBirth instanceof Date) {
        dataToSave.dateOfBirth = dataToSave.dateOfBirth.toISOString();
      }
    }

    updatePlayerMutation.mutate(dataToSave);
  };

  const handleInputChange = (field: keyof User, value: any) => {
    setEditData(prev => ({ ...prev, [field]: value }));
  };


  const getStatusColor = () => {
    if (!player) return 'bg-blue-500 text-white';
    switch (player.status) {
      case 'Fit':
        return 'bg-green-500 text-white';
      case 'Injured':
        return 'bg-red-500 text-white';
      case 'Retired':
        return 'bg-gray-500 text-white';
      default:
        return 'bg-blue-500 text-white';
    }
  };

  const getAccountStatusColor = (status: string) => {
    switch (status) {
      case "Active": return "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200";
      case "Suspended": return "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200";
      case "Retired": return "bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200";
      default: return "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200"; // Draft
    }
  };

  const getPositionCategory = (position: string): string => {
    if (position.includes('GK') || position.includes('Goalkeeper')) return 'GK';
    if (position.includes('CB') || position.includes('LB') || position.includes('RB') || 
        position.includes('LWB') || position.includes('RWB') || position.includes('Defense')) return 'DEF';
    if (position.includes('CM') || position.includes('CDM') || position.includes('CAM') || 
        position.includes('LM') || position.includes('RM') || position.includes('Midfield')) return 'MID';
    if (position.includes('ST') || position.includes('CF') || position.includes('LW') || 
        position.includes('RW') || position.includes('Forward')) return 'FWD';
    return position;
  };

  const getPositionColor = () => {
    if (!player || !primaryTeam) return 'bg-gray-100 text-gray-800';
    const playerPosition = userTeams[0]?.position || 'Unknown';
    const positionCategory = getPositionCategory(playerPosition);
    switch (positionCategory) {
      case 'GK':
        return 'bg-purple-100 text-purple-800';
      case 'DEF':
        return 'bg-blue-100 text-blue-800';
      case 'MID':
        return 'bg-green-100 text-green-800';
      case 'FWD':
        return 'bg-red-100 text-red-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  if (isLoading) {
    return (
      <MainLayout title="Loading..." subtitle="Loading player details...">
        <div className="flex items-center justify-center h-64">
          <div className="text-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto"></div>
            <p className="mt-2 text-muted-foreground">Loading player details...</p>
          </div>
        </div>
      </MainLayout>
    );
  }

  if (!player) {
    return (
      <MainLayout title="Player Not Found" subtitle="The requested player could not be found">
        <div className="text-center py-8">
          <p className="text-muted-foreground mb-4">The player you're looking for doesn't exist or has been deleted.</p>
          <Button onClick={() => window.history.back()}>
            <ArrowLeft className="mr-2 h-4 w-4" />
            Go Back
          </Button>
        </div>
      </MainLayout>
    );
  }

  const getPlayerInitials = (name: string) => {
    const names = name.split(' ');
    if (names.length >= 2) {
      return `${names[0][0]}${names[names.length - 1][0]}`.toUpperCase();
    }
    return name.substring(0, 2).toUpperCase();
  };

  // Get club's primary color, fallback to default if not set
  const clubPrimaryColor = (selectedClub?.colors as any)?.primary || '#dc2626';

  // Function to determine if a color is light or dark for text contrast
  const isLightColor = (hexColor: string) => {
    const color = hexColor.replace('#', '');
    const r = parseInt(color.substr(0, 2), 16);
    const g = parseInt(color.substr(2, 2), 16);
    const b = parseInt(color.substr(4, 2), 16);
    const brightness = ((r * 299) + (g * 587) + (b * 114)) / 1000;
    return brightness > 155;
  };

  const textColor = isLightColor(clubPrimaryColor) ? '#000000' : '#ffffff';
  const labelColor = isLightColor(clubPrimaryColor) ? 'rgba(0,0,0,0.7)' : 'rgba(255,255,255,0.7)';

  const solidStyle = {
    backgroundColor: source === "profiles" ? 'hsl(var(--background) / 1)' : '#f8f9fa',
    position: 'relative' as const,
    overflow: 'hidden' as const,
  } as React.CSSProperties;

  return (
    <MainLayout 
      title="VIEW SQUAD MEMBER" 
      subtitle={`${player.firstName} ${player.lastName}`}
    >
      <div className="-m-6" data-testid={`player-details-${player.id}`}>
        {/* Player Header Card with Integrated Tabs */}
        <Tabs defaultValue="details" value={activeTab} onValueChange={setActiveTab} className="w-full flex flex-col">
          <Card className="w-full relative overflow-hidden border-0 shadow-none rounded-none" style={{...solidStyle, borderColor: clubPrimaryColor}}>
            <CardContent className="p-0">
              {/* Honeycomb Background Pattern */}
              <div 
                className="absolute inset-0 pointer-events-none"
                style={{
                  '--cell-size': '12vw',
                  '--columns': '6',
                  '--gap': '0.3vw',
                  '--cell-height': 'calc(var(--cell-size) * 1.15)',
                  '--container-width': 'calc((var(--cell-size) + var(--gap)) * var(--columns))',
                  '--row-height': 'calc(var(--cell-size) * 0.8666)',
                  '--margin-offset': 'calc(var(--cell-size) / 2 + var(--gap) / 2)',
                } as React.CSSProperties}
              >
                <div 
                  className="honeycomb absolute inset-0"
                  style={{
                    display: 'grid',
                    width: 'var(--container-width)',
                    margin: '0 auto',
                    transform: 'translateX(calc(var(--margin-offset) / -2)) translateX(-120px) translateY(-150px)',
                    gridTemplateColumns: 'repeat(6, minmax(var(--cell-size), 1fr))',
                    gridAutoRows: 'var(--row-height)',
                    gap: 'var(--gap)',
                    opacity: 0.15
                  }}
                >
                  {/* Generate honeycomb cells */}
                  {Array.from({ length: 60 }, (_, index) => (
                    <div
                      key={index}
                      className="cell"
                      style={{
                        width: 'var(--cell-size)',
                        height: 'var(--cell-height)',
                        margin: '0',
