export type UserRole = 'admin' | 'coach' | 'player';

export type FixtureStatus = 'SCHEDULED' | 'COMPLETED' | 'CANCELLED' | 'NO_CONTEST';

export type FixtureType = 'HOME' | 'AWAY' | 'NEUTRAL';

export type Position = 'GK' | 'CB' | 'LB' | 'RB' | 'CDM' | 'CM' | 'CAM' | 'LM' | 'RM' | 'LW' | 'RW' | 'ST' | 'CF';

export interface TeamStatistics {
  totalPlayers: number;
  matchesPlayed: number;
  wins: number;
  draws: number;
  losses: number;
  totalGoals: number;
  totalGoalsConceded: number;
  goalDifference: number;
  totalAssists: number;
  topScorer?: {
    name: string;
    goals: number;
    position: string;
  };
  topAssist?: {
    name: string;
    assists: number;
    position: string;
  };
}

export interface NavigationItem {
  id: string;
  label: string;
  icon: string;
  tooltip: string;
}

export interface ColorTheme {
  name: string;
  light: { accent: string; light: string };
  dark: { accent: string; light: string };
}

// Match event types for timeline and analysis components
export interface MatchEvent {
  id: string;
  index: number;
  period: number;
  timestamp: string;
  minute: number;
  second: number;
  type: {
    id: number;
    name: string;
  };
  team: {
    id: number;
    name: string;
  };
  player?: {
    id: number;
    name: string;
  };
  location?: number[];
  under_pressure?: boolean;
