import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Edit, Trash2, Star, User as UserIcon, Pencil, Check, X, UserMinus } from "lucide-react";
import { User } from "@shared/schema";
import { useLocation } from "wouter";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useClubTheme } from "@/hooks/use-club-theme";

// Define Player type for compatibility with team data
type Player = User & {
  jerseyNumber?: number | null;
  position?: string;
  starPlayer?: boolean;
  keyPlayer?: boolean;
  fitnessStatus?: string;
};

interface PlayerCardProps {
  player: Player;
  teamId?: string;
  onEdit?: (player: Player) => void;
  onDelete?: (player: Player) => void;
  onRemoveFromSquad?: (player: Player) => void;
  onToggleKeyPlayer?: (player: Player) => void;
  onUpdateStatus?: (player: Player, newStatus: string) => void;
  onUpdateJerseyNumber?: (playerId: string, teamId: string, jerseyNumber: number) => void;
  onUpdatePosition?: (playerId: string, teamId: string, position: string) => void;
}

export function PlayerCard({ player, teamId, onEdit, onDelete, onRemoveFromSquad, onToggleKeyPlayer, onUpdateStatus, onUpdateJerseyNumber, onUpdatePosition }: PlayerCardProps) {
  const [, setLocation] = useLocation();
  const [isEditingStatus, setIsEditingStatus] = useState(false);
  const [isEditingJersey, setIsEditingJersey] = useState(false);
  const [editJerseyValue, setEditJerseyValue] = useState(player.jerseyNumber?.toString() || '');
  const [isEditingPosition, setIsEditingPosition] = useState(false);
  const { clubPrimary } = useClubTheme();

  const getStatusColor = () => {
    const status = player.fitnessStatus || player.status;
    switch (status) {
      case 'Fit':
        return 'bg-green-500 text-white';
      case 'Injured':
        return 'bg-red-500 text-white';
      case 'Retired':
        return 'bg-gray-500 text-white';
      default:
        return 'bg-blue-500 text-white';
    }
  };

  const getPositionCategory = (position: string): string => {
    if (position.includes('GK') || position.includes('Goalkeeper')) return 'GK';
    if (position.includes('CB') || position.includes('LB') || position.includes('RB') || 
        position.includes('LWB') || position.includes('RWB') || position.includes('Defense')) return 'DEF';
    if (position.includes('CM') || position.includes('CDM') || position.includes('CAM') || 
        position.includes('LM') || position.includes('RM') || position.includes('DM') || 
        position.includes('AM') || position.includes('Midfield')) return 'MID';
    if (position.includes('ST') || position.includes('CF') || position.includes('LW') || 
        position.includes('RW') || position.includes('Forward')) return 'FWD';
    return 'MID'; // Default to midfield instead of returning position
  };

  const getPositionColor = () => {
    const positionCategory = getPositionCategory(player.position || 'MID');
    switch (positionCategory) {
      case 'GK':
        return 'bg-purple-100 text-purple-800';
      case 'DEF':
        return 'bg-blue-100 text-blue-800';
      case 'MID':
        return 'bg-green-100 text-green-800';
      case 'FWD':
        return 'bg-red-100 text-red-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const handleSaveJersey = () => {
    const newJerseyNumber = parseInt(editJerseyValue);
    if (!isNaN(newJerseyNumber) && teamId && onUpdateJerseyNumber) {
      onUpdateJerseyNumber(player.id, teamId, newJerseyNumber);
    }
    setIsEditingJersey(false);
  };

  const handleCancelJersey = () => {
    setEditJerseyValue(player.jerseyNumber?.toString() || '');
    setIsEditingJersey(false);
  };

  const getPositionOptions = () => {
    if (player.role === 'Coach') {
      return [
        { value: 'Head Coach', label: 'Head Coach' },
        { value: 'Assistant Coach', label: 'Assistant Coach' },
      ];
    }
    return [
      { value: 'Goalkeeper', label: 'Goalkeeper' },
      { value: 'Defender', label: 'Defender' },
      { value: 'Midfield', label: 'Midfield' },
      { value: 'Forward', label: 'Forward' },
    ];
  };

  const handleUpdatePosition = (newPosition: string) => {
    if (teamId && onUpdatePosition) {
      onUpdatePosition(player.id, teamId, newPosition);
    }
    setIsEditingPosition(false);
  };

  // Function to get player display (jersey number)
  const getPlayerDisplay = () => {
    // Show jersey number if available, otherwise ?
    const displayNumber = player.jerseyNumber !== undefined && player.jerseyNumber !== null ? player.jerseyNumber : '?';

    if (isEditingJersey) {
      return (
        <div className="flex items-center space-x-1">
          <Input
            type="number"
            value={editJerseyValue}
            onChange={(e) => setEditJerseyValue(e.target.value)}
            className="w-12 h-8 text-center text-sm"
            min="1"
            max="99"
            onClick={(e) => e.stopPropagation()}
          />
          <Button
            variant="ghost"
            size="sm"
            onClick={(e) => {
              e.stopPropagation();
              handleSaveJersey();
            }}
            className="h-6 w-6 p-0"
          >
            <Check className="h-3 w-3 text-green-600" />
          </Button>
          <Button
            variant="ghost"
            size="sm"
            onClick={(e) => {
              e.stopPropagation();
              handleCancelJersey();
            }}
            className="h-6 w-6 p-0"
          >
            <X className="h-3 w-3 text-red-600" />
          </Button>
        </div>
      );
    }

    return (
      <div 
        className="h-8 w-8 rounded-full flex items-center justify-center text-white text-sm font-bold border-2 cursor-pointer hover:opacity-80"
        style={{ 
          backgroundColor: clubPrimary,
          borderColor: clubPrimary
        }}
        onClick={(e) => {
          e.stopPropagation();
          setIsEditingJersey(true);
        }}
        title="Click to edit jersey number"
      >
        {displayNumber}
      </div>
    );
  };

  return (
    <Card 
      data-testid={`card-player-${player.id}`} 
      className="border rounded-lg cursor-pointer"
      onClick={(e) => {
        // Only trigger navigation if not clicking on interactive elements
        if (!e.defaultPrevented) {
          setLocation(`/users/${player.id}`);
        }
      }}
    >
      <CardContent className="p-3">
        <div className="flex items-center justify-between min-h-[50px]">
          {/* Player Avatar */}
          <div className="flex items-center space-x-3">
            <div className="w-12 h-12 flex items-center justify-center">
              {getPlayerDisplay()}
            </div>

            {/* Main Content */}
            <div className="flex-1">
              <div className="flex items-center space-x-2">
                <h3 className="font-semibold text-lg text-foreground">{player.firstName} {player.lastName}</h3>
              </div>
              <div className="flex items-center space-x-2">
                {isEditingPosition ? (
                  <Select
                    value={player.position || ''}
                    onValueChange={handleUpdatePosition}
                  >
                    <SelectTrigger className="w-40 h-7 text-xs" onClick={(e) => e.stopPropagation()}>
                      <SelectValue placeholder="Select position" />
                    </SelectTrigger>
                    <SelectContent>
                      {getPositionOptions().map(option => (
                        <SelectItem key={option.value} value={option.value}>
                          {option.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                ) : (
                  <>
                    <p className="text-sm text-muted-foreground">
                      {player.position || 'No position'}
                    </p>
                    {onUpdatePosition && teamId && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={(e) => {
                          e.stopPropagation();
                          setIsEditingPosition(true);
                        }}
                        className="h-5 w-5 p-0 text-muted-foreground hover:text-foreground"
                        title="Edit position"
                      >
                        <Pencil className="h-3 w-3" />
                      </Button>
                    )}
                  </>
                )}
              </div>
            </div>
          </div>

          {/* Right side - Status and Actions */}
          <div className="flex items-center space-x-3">
            {/* Status */}
            {isEditingStatus ? (
              <Select
                value={player.fitnessStatus || player.status || "Fit"}
                onValueChange={(newStatus) => {
                  if (onUpdateStatus) {
                    onUpdateStatus(player, newStatus);
                  }
                  setIsEditingStatus(false);
                }}
              >
                <SelectTrigger className="w-20 h-7 text-xs">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Fit">Fit</SelectItem>
                  <SelectItem value="Injured">Injured</SelectItem>
                  <SelectItem value="Retired">Retired</SelectItem>
                </SelectContent>
              </Select>
            ) : (
              <Badge 
                className={`text-xs px-3 py-1 cursor-pointer hover:opacity-80 ${getStatusColor()}`}
                onClick={(e) => {
                  e.stopPropagation();
                  setIsEditingStatus(true);
                }}
                title="Click to edit status"
              >
                {player.fitnessStatus || player.status || "Fit"}
              </Badge>
            )}

            {/* Star Toggle */}
            {onToggleKeyPlayer && (
              <Button
                variant="ghost"
                size="sm"
                onClick={(e) => {
                  e.stopPropagation();
                  onToggleKeyPlayer(player);
                }}
                className="h-8 w-8 p-0"
                data-testid={`button-star-toggle-${player.id}`}
                title={player.keyPlayer ? 'Remove star player status' : 'Make star player'}
              >
                <Star 
                  className={`h-4 w-4 transition-colors ${
                    player.keyPlayer 
                      ? 'text-orange-500 fill-orange-500' 
                      : 'text-gray-300 hover:text-orange-300'
                  }`} 
                />
              </Button>
            )}

            {/* Remove from Squad Button */}
            {onRemoveFromSquad && teamId && (
              <Button
                variant="ghost"
                size="sm"
                onClick={(e) => {
                  e.stopPropagation();
                  onRemoveFromSquad(player);
                }}
                className="h-8 w-8 p-0 text-orange-600 hover:text-orange-700 hover:bg-orange-50"
                data-testid={`button-remove-squad-${player.id}`}
                title="Remove from squad"
              >
                <UserMinus className="h-4 w-4" />
              </Button>
            )}

            {/* Delete Button */}
            {onDelete && (
              <Button
                variant="ghost"
                size="sm"
                onClick={(e) => {
                  e.stopPropagation();
                  onDelete(player);
                }}
                className="h-8 w-8 p-0 text-red-600 hover:text-red-700 hover:bg-red-50"
                data-testid={`button-delete-${player.id}`}
                title="Delete player"
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

client/src/hooks/use-club-theme.ts.content:
import { useEffect } from "react";
import { useClub } from "@/contexts/club-context";

/**
 * Hook that dynamically updates CSS variables for club branding colors
 * This allows using Tailwind classes like text-club-primary throughout the app
 */
export function useClubTheme() {
  const { selectedClub } = useClub();

  useEffect(() => {
    const root = document.documentElement;

    if (selectedClub?.colors) {
      const clubColors = selectedClub.colors as { primary?: string; secondary?: string };

      // Update CSS variables for club colors
      if (clubColors.primary) {
        root.style.setProperty('--club-primary', clubColors.primary);
      }

      if (clubColors.secondary) {
        root.style.setProperty('--club-secondary', clubColors.secondary);
      }
    } else {
      // Reset to defaults when no club selected
      root.style.setProperty('--club-primary', '#dc2626');
      root.style.setProperty('--club-secondary', '#000000');
    }
  }, [selectedClub]);

  // Return the current colors for components that need direct access
  const clubColors = selectedClub?.colors as { primary?: string; secondary?: string } | null;
  return {
    clubPrimary: clubColors?.primary || '#dc2626',
    clubSecondary: clubColors?.secondary || '#000000',
  };
}

