server/objectStorage.ts.content:
import { Storage, File } from "@google-cloud/storage";
import { Response } from "express";
import { randomUUID } from "crypto";

const REPLIT_SIDECAR_ENDPOINT = "http://127.0.0.1:1106";

// The object storage client is used to interact with the object storage service.
export const objectStorageClient = new Storage({
  credentials: {
    audience: "replit",
    subject_token_type: "access_token",
    token_url: `${REPLIT_SIDECAR_ENDPOINT}/token`,
    type: "external_account",
    credential_source: {
      url: `${REPLIT_SIDECAR_ENDPOINT}/credential`,
      format: {
        type: "json",
        subject_token_field_name: "access_token",
      },
    },
    universe_domain: "googleapis.com",
  },
  projectId: "",
});

export class ObjectNotFoundError extends Error {
  constructor() {
    super("Object not found");
    this.name = "ObjectNotFoundError";
    Object.setPrototypeOf(this, ObjectNotFoundError.prototype);
  }
}

// The object storage service is used to interact with the object storage service.
export class ObjectStorageService {
  constructor() {}

  // Gets the private object directory.
  getPrivateObjectDir(): string {
    const dir = process.env.PRIVATE_OBJECT_DIR || "";
    if (!dir) {
      throw new Error(
        "PRIVATE_OBJECT_DIR not set. Create a bucket in 'Object Storage' " +
          "tool and set PRIVATE_OBJECT_DIR env var."
      );
    }
    return dir;
  }

  // Gets the upload URL for an object entity.
  async getObjectEntityUploadURL(): Promise<string> {
    const privateObjectDir = this.getPrivateObjectDir();
    if (!privateObjectDir) {
      throw new Error(
        "PRIVATE_OBJECT_DIR not set. Create a bucket in 'Object Storage' " +
          "tool and set PRIVATE_OBJECT_DIR env var."
      );
    }

    const objectId = randomUUID();
    const fullPath = `${privateObjectDir}/uploads/${objectId}`;

    const { bucketName, objectName } = parseObjectPath(fullPath);

    // Sign URL for PUT method with TTL
    return signObjectURL({
      bucketName,
      objectName,
      method: "PUT",
      ttlSec: 900,
    });
  }

  // Gets the upload URL for a logo.
  async getLogoUploadURL(): Promise<string> {
    const privateObjectDir = this.getPrivateObjectDir();
    if (!privateObjectDir) {
      throw new Error(
        "PRIVATE_OBJECT_DIR not set. Create a bucket in 'Object Storage' " +
          "tool and set PRIVATE_OBJECT_DIR env var."
      );
    }

    const logoId = randomUUID();
    const fullPath = `${privateObjectDir}/logos/${logoId}`;

    const { bucketName, objectName } = parseObjectPath(fullPath);

    // Sign URL for PUT method with TTL
    return signObjectURL({
      bucketName,
      objectName,
      method: "PUT",
      ttlSec: 900,
    });
  }

  // Gets the upload URL for a user photo.
  async getUserPhotoUploadURL(): Promise<string> {
    const privateObjectDir = this.getPrivateObjectDir();
    if (!privateObjectDir) {
      throw new Error(
        "PRIVATE_OBJECT_DIR not set. Create a bucket in 'Object Storage' " +
          "tool and set PRIVATE_OBJECT_DIR env var."
      );
    }

    const photoId = randomUUID();
    const fullPath = `${privateObjectDir}/user-photos/${photoId}`;

    const { bucketName, objectName } = parseObjectPath(fullPath);

    // Sign URL for PUT method with TTL
    return signObjectURL({
      bucketName,
      objectName,
      method: "PUT",
      ttlSec: 900,
    });
  }

  // Gets the object entity file from the object path.
  async getObjectEntityFile(objectPath: string): Promise<File> {
    if (!objectPath.startsWith("/objects/")) {
      throw new ObjectNotFoundError();
    }

    const parts = objectPath.slice(1).split("/");
    if (parts.length < 2) {
      throw new ObjectNotFoundError();
    }

    const entityId = parts.slice(1).join("/");
    let entityDir = this.getPrivateObjectDir();
    if (!entityDir.endsWith("/")) {
      entityDir = `${entityDir}/`;
    }
    const objectEntityPath = `${entityDir}${entityId}`;
    const { bucketName, objectName } = parseObjectPath(objectEntityPath);
    const bucket = objectStorageClient.bucket(bucketName);
    const objectFile = bucket.file(objectName);
    const [exists] = await objectFile.exists();
    if (!exists) {
      throw new ObjectNotFoundError();
    }
    return objectFile;
  }

  normalizeObjectEntityPath(rawPath: string): string {
    if (!rawPath.startsWith("https://storage.googleapis.com/")) {
      return rawPath;
    }

    // Extract the path from the URL by removing query parameters and domain
    const url = new URL(rawPath);
    const rawObjectPath = url.pathname;

    let objectEntityDir = this.getPrivateObjectDir();
    if (!objectEntityDir.endsWith("/")) {
      objectEntityDir = `${objectEntityDir}/`;
    }

    if (!rawObjectPath.startsWith(objectEntityDir)) {
      return rawObjectPath;
    }

    // Extract the entity ID from the path
    const entityId = rawObjectPath.slice(objectEntityDir.length);
    return `/objects/${entityId}`;
  }

  // Downloads an object to the response.
  async downloadObject(file: File, res: Response, cacheTtlSec: number = 3600) {
    try {
      // Get file metadata
      const [metadata] = await file.getMetadata();

      // Set appropriate headers
      res.set({
        "Content-Type": metadata.contentType || "application/octet-stream",
        "Content-Length": metadata.size,
        "Cache-Control": `public, max-age=${cacheTtlSec}`,
      });

      // Stream the file to the response
      const stream = file.createReadStream();

      stream.on("error", (err: any) => {
        console.error("Stream error:", err);
        if (!res.headersSent) {
          res.status(500).json({ error: "Error streaming file" });
        }
      });

      stream.pipe(res);
    } catch (error) {
      console.error("Error downloading file:", error);
      if (!res.headersSent) {
        res.status(500).json({ error: "Error downloading file" });
      }
    }
  }

  // Normalize logo path from upload URL to serve path
  normalizeLogoPath(rawPath: string): string {
    if (!rawPath.startsWith("https://storage.googleapis.com/")) {
      return rawPath;
    }

    // Extract the path from the URL by removing query parameters and domain
    const url = new URL(rawPath);
    const rawObjectPath = url.pathname;

    let logoDir = this.getPrivateObjectDir();
    if (!logoDir.endsWith("/")) {
      logoDir = `${logoDir}/`;
    }

    if (!rawObjectPath.startsWith(logoDir)) {
      return rawObjectPath;
    }

    // Extract the entity ID from the path (this includes logos/ prefix)
    const entityId = rawObjectPath.slice(logoDir.length);

    // Strip the logos/ prefix if it exists since we'll add it back
    const logoId = entityId.startsWith('logos/') ? entityId.slice(6) : entityId;
    return `/logos/${logoId}`;
  }

  // Gets the logo file from the logo path.
  async getLogoFile(logoPath: string): Promise<File> {
    if (!logoPath.startsWith("/logos/")) {
      throw new ObjectNotFoundError();
    }

    const parts = logoPath.slice(1).split("/");
    if (parts.length < 2) {
      throw new ObjectNotFoundError();
    }

    const logoId = parts.slice(1).join("/");
    let logoDir = this.getPrivateObjectDir();
    if (!logoDir.endsWith("/")) {
      logoDir = `${logoDir}/`;
    }

    // Try primary path: logos are stored in the logos/ subdirectory
    const logoObjectPath = `${logoDir}logos/${logoId}`;

    const { bucketName, objectName } = parseObjectPath(logoObjectPath);
    const bucket = objectStorageClient.bucket(bucketName);
    let logoFile = bucket.file(objectName);
    let [exists] = await logoFile.exists();

    // Fallback: if path is /logos/uploads/... and not found in logos/uploads/,
    // try looking in uploads/ directory (legacy path format)
    if (!exists && logoId.startsWith("uploads/")) {
      const legacyUploadId = logoId.slice("uploads/".length);
      const legacyObjectPath = `${logoDir}uploads/${legacyUploadId}`;
      const { bucketName: legacyBucket, objectName: legacyObject } = parseObjectPath(legacyObjectPath);
      logoFile = bucket.file(legacyObject);
      [exists] = await logoFile.exists();
    }

    if (!exists) {
      throw new ObjectNotFoundError();
    }
    return logoFile;
  }

  // Gets the upload file from the upload path.
  async getUploadFile(uploadPath: string): Promise<File> {
    if (!uploadPath.startsWith("/uploads/")) {
      throw new ObjectNotFoundError();
    }

    const uploadId = uploadPath.slice("/uploads/".length);
    let uploadDir = this.getPrivateObjectDir();
    if (!uploadDir.endsWith("/")) {
      uploadDir = `${uploadDir}/`;
    }

    const uploadObjectPath = `${uploadDir}uploads/${uploadId}`;

    const { bucketName, objectName } = parseObjectPath(uploadObjectPath);
    const bucket = objectStorageClient.bucket(bucketName);
    const uploadFile = bucket.file(objectName);
    const [exists] = await uploadFile.exists();

    if (!exists) {
      throw new ObjectNotFoundError();
    }
    return uploadFile;
  }

  // Normalize user photo path from upload URL to serve path
  normalizeUserPhotoPath(rawPath: string): string {
    if (!rawPath.startsWith("https://storage.googleapis.com/")) {
      return rawPath;
    }

    // Extract the path from the URL by removing query parameters and domain
    const url = new URL(rawPath);
    const rawObjectPath = url.pathname;

    let photoDir = this.getPrivateObjectDir();
    if (!photoDir.endsWith("/")) {
      photoDir = `${photoDir}/`;
    }

    if (!rawObjectPath.startsWith(photoDir)) {
      return rawObjectPath;
    }

    // Extract the entity ID from the path
    const entityId = rawObjectPath.slice(photoDir.length);
    return `/user-photos/${entityId}`;
  }

  // Gets the user photo file from the photo path.
  async getUserPhotoFile(photoPath: string): Promise<File> {
    if (!photoPath.startsWith("/user-photos/")) {
      throw new ObjectNotFoundError();
    }

    const parts = photoPath.slice(1).split("/");
    if (parts.length < 2) {
      throw new ObjectNotFoundError();
    }

    const photoId = parts.slice(1).join("/");
    let photoDir = this.getPrivateObjectDir();
    if (!photoDir.endsWith("/")) {
      photoDir = `${photoDir}/`;
    }

    // Check if photoId already includes user-photos/ prefix
    const finalPhotoId = photoId.startsWith('user-photos/') ? photoId : `user-photos/${photoId}`;
    const photoObjectPath = `${photoDir}${finalPhotoId}`;

    const { bucketName, objectName } = parseObjectPath(photoObjectPath);
    const bucket = objectStorageClient.bucket(bucketName);
    const photoFile = bucket.file(objectName);
    const [exists] = await photoFile.exists();

    if (!exists) {
      throw new ObjectNotFoundError();
    }
    return photoFile;
  }
}

function parseObjectPath(path: string): {
  bucketName: string;
  objectName: string;
} {
  if (!path.startsWith("/")) {
    path = `/${path}`;
  }
  const pathParts = path.split("/");
  if (pathParts.length < 3) {
    throw new Error("Invalid path: must contain at least a bucket name");
  }

  const bucketName = pathParts[1];
  const objectName = pathParts.slice(2).join("/");

  return {
    bucketName,
    objectName,
  };
}

async function signObjectURL({
  bucketName,
  objectName,
  method,
  ttlSec,
}: {
  bucketName: string;
  objectName: string;
  method: "GET" | "PUT" | "DELETE" | "HEAD";
  ttlSec: number;
}): Promise<string> {
  const request = {
    bucket_name: bucketName,
    object_name: objectName,
    method,
    expires_at: new Date(Date.now() + ttlSec * 1000).toISOString(),
  };
  const response = await fetch(
    `${REPLIT_SIDECAR_ENDPOINT}/object-storage/signed-object-url`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(request),
    }
  );
  if (!response.ok) {
    throw new Error(
      `Failed to sign object URL, errorcode: ${response.status}, ` +
        `make sure you're running on Replit`
    );
  }

  const { signed_url: signedURL } = await response.json();
  return signedURL;
}

