                            data-testid="input-home-score"
                            placeholder="-"
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="awayScore"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Away Score</FormLabel>
                        <FormControl>
                          <Input
                            type="number"
                            {...field}
                            value={field.value ?? ""}
                            onChange={(e) => field.onChange(e.target.value === "" ? undefined : parseInt(e.target.value))}
                            data-testid="input-away-score"
                            placeholder="-"
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>

                {/* Hidden opponent name field */}
                <FormField
                  control={form.control}
                  name="opponent"
                  render={({ field }) => (
                    <input type="hidden" {...field} />
                  )}
                />

                <div className="space-y-6 pt-6">
                  <Form {...opponentForm}>
                    {/* Opposition Colors Section */}
                    <div className="space-y-4">
                      <div className="border-b pb-2">
                        <h4 className="text-sm font-semibold">Opposition Colors</h4>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                        <FormField
                          control={opponentForm.control}
                          name="primaryColor"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Primary Color</FormLabel>
                              <FormControl>
                                <div className="flex gap-2 items-center">
                                  <Input 
                                    {...field} 
                                    type="color" 
                                    className="h-10 w-16 cursor-pointer p-1"
                                    data-testid="input-opponent-primary-color"
                                  />
                                  <Input 
                                    value={field.value}
                                    onChange={(e) => field.onChange(e.target.value)}
                                    placeholder="#000000"
                                    className="flex-1 font-mono text-sm"
                                  />
                                </div>
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />

                        <FormField
                          control={opponentForm.control}
                          name="secondaryColor"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Secondary Color</FormLabel>
                              <FormControl>
                                <div className="flex gap-2 items-center">
                                  <Input 
                                    {...field} 
                                    type="color" 
                                    className="h-10 w-16 cursor-pointer p-1"
                                    data-testid="input-opponent-secondary-color"
                                  />
                                  <Input 
                                    value={field.value}
                                    onChange={(e) => field.onChange(e.target.value)}
                                    placeholder="#FFFFFF"
                                    className="flex-1 font-mono text-sm"
                                  />
                                </div>
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>
                    </div>

                    {/* Team Logo Section */}
                    <div className="space-y-4">
                      <div className="border-b pb-2">
                        <h4 className="text-sm font-semibold">Team Logo</h4>
                      </div>

                      <FormField
                        control={opponentForm.control}
                        name="logoPath"
                        render={({ field }) => (
                          <FormItem>
                            <FormControl>
                              <LogoUpload
                                teamName={showNewOpponentInput ? (newOpponentName || "Opponent") : (oppositionTeams.find(t => t.id === form.watch("oppositionTeamId"))?.name || "Opponent")}
                                currentLogo={field.value}
                                onUploadComplete={(logoPath: string) => {
                                  field.onChange(logoPath);
                                  toast({
                                    title: "Logo Uploaded",
                                    description: "Logo has been uploaded successfully",
                                  });
                                }}
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>
                  </Form>
                </div>

                <div className="flex justify-end gap-2 pt-4">
                  <Button type="button" variant="outline" onClick={() => setOpen(false)}>
                    Cancel
                  </Button>
                  <Button 
                    type="button"
                    data-testid="button-save-fixture"
                    disabled={createCompetitionMutation.isPending || createOpponentMutation.isPending}
                    onClick={() => {
                      if (showNewOpponentInput && newOpponentName.trim()) {
                        form.setValue("opponent", newOpponentName.trim());
                        form.setValue("oppositionTeamId", "pending");
                      }
                      form.handleSubmit(handleSubmit)();
                    }}
                  >
                    {createCompetitionMutation.isPending || createOpponentMutation.isPending ? "Saving..." : "Save Changes"}
                  </Button>
                </div>
              </form>
            </Form>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}

