import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { MainLayout } from "@/components/layout/main-layout";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Slider } from "@/components/ui/slider";
import { Upload, Wand2, Save, CheckCircle, AlertCircle, Info, Edit3, Sun, Moon } from "lucide-react";
import { OppositionTeam } from "@shared/schema";
import { BackgroundRemover, BackgroundRemovalOptions } from "@/utils/backgroundRemoval";
import { useClub } from "@/contexts/club-context";
import { useToast } from "@/hooks/use-toast";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { ThemedLogoContainer } from "@/components/ui/themed-logo-container";

export default function LogoManagement() {
  const { selectedClub: currentClub } = useClub();
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [selectedTeam, setSelectedTeam] = useState<string>("");
  const [processing, setProcessing] = useState(false);
  const [processedImageUrl, setProcessedImageUrl] = useState<string | null>(null);
  const [originalImageUrl, setOriginalImageUrl] = useState<string | null>(null);
  const [processingMode, setProcessingMode] = useState<'smart' | 'color' | 'manual'>('smart');
  const [threshold, setThreshold] = useState(30);
  const [showTip, setShowTip] = useState(false);
  const [logoSize, setLogoSize] = useState(200);
  const [darkMode, setDarkMode] = useState(false);
  const { toast } = useToast();

  const { data: oppositionTeams } = useQuery<OppositionTeam[]>({ 
    queryKey: ["/api/opposition-teams", currentClub?.id],
    queryFn: async () => {
      const url = currentClub?.id ? `/api/opposition-teams?clubId=${currentClub.id}` : '/api/opposition-teams';
      const res = await fetch(url);
      if (!res.ok) throw new Error('Failed to fetch opposition teams');
      return res.json();
    }
  });

  const saveMutation = useMutation({
    mutationFn: async ({ teamId, logoData }: { teamId: string; logoData: Blob }) => {
      // First, upload the logo file to the server
      const formData = new FormData();
      formData.append('logo', logoData, `${teamId}-logo.png`);
      formData.append('teamId', teamId);

      const response = await fetch('/api/opposition-teams/logo', {
        method: 'POST',
        body: formData,
      });
      return response;
    },
    onSuccess: () => {
      toast({
        title: "Logo Saved",
        description: "Team logo has been processed and saved successfully!",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/opposition-teams"] });
      // Reset form
      setSelectedFile(null);
      setSelectedTeam("");
      setProcessedImageUrl(null);
      setOriginalImageUrl(null);
      setShowTip(false);
      setProcessingMode('smart');
      setThreshold(30);
      setLogoSize(200);
    },
    onError: (error) => {
      toast({
        title: "Save Failed",
        description: "Failed to save the logo. Please try again.",
        variant: "destructive",
      });
      console.error('Save error:', error);
    },
  });

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setSelectedFile(file);
    setOriginalImageUrl(URL.createObjectURL(file));

    // Show tip for larger images or potential logos with isolated elements
    const img = new Image();
    img.onload = () => {
      if (img.width > 200 || img.height > 200 || file.name.toLowerCase().includes('logo')) {
        setShowTip(true);
      }
    };
    img.src = URL.createObjectURL(file);

    // Automatically process the image
    await processImageWithCurrentSettings(file);
  };

  const handleSave = async () => {
    if (!selectedTeam || !processedImageUrl) {
      toast({
        title: "Missing Information",
        description: "Please select a team and process an image first.",
        variant: "destructive",
      });
      return;
    }

    // Convert the processed image URL to a blob
    const response = await fetch(processedImageUrl);
    const logoData = await response.blob();

    saveMutation.mutate({ teamId: selectedTeam, logoData });
  };

  const processImageWithCurrentSettings = async (file: File) => {
    setProcessing(true);
    try {
      const backgroundRemover = new BackgroundRemover();
      const options: BackgroundRemovalOptions = {
        mode: processingMode,
        tolerance: threshold,
        preserveInternalWhite: true,
        resizeWidth: logoSize
      };

      const processedBlob = await backgroundRemover.removeBackground(file, options);
      const processedUrl = URL.createObjectURL(processedBlob);
      setProcessedImageUrl(processedUrl);
    } catch (error) {
      console.error('Processing error:', error);
      toast({
        title: "Processing Failed",
        description: "Failed to remove background. Please try a different image.",
        variant: "destructive",
      });
    } finally {
      setProcessing(false);
    }
  };

  const handleModeChange = async (newMode: 'smart' | 'color' | 'manual') => {
    setProcessingMode(newMode);
    if (selectedFile) {
      await processImageWithCurrentSettings(selectedFile);
    }
  };

  const handleThresholdChange = async (value: number[]) => {
    setThreshold(value[0]);
    if (selectedFile && processingMode === 'manual') {
      await processImageWithCurrentSettings(selectedFile);
    }
  };

  const selectedTeamData = oppositionTeams?.find(team => team.id === selectedTeam);

  const handleEditExistingLogo = (team: OppositionTeam) => {
    setSelectedTeam(team.id);
    if (team.logoPath) {
      // Load the existing logo for editing
      setOriginalImageUrl(team.logoPath);
      setProcessedImageUrl(null);
      setSelectedFile(null);
      setShowTip(true);
    }
    // Scroll to the upload section
    setTimeout(() => {
      document.getElementById('upload-section')?.scrollIntoView({ 
        behavior: 'smooth',
        block: 'start'
      });
    }, 100);
  };

  const handleRemoveBackground = async (team: OppositionTeam) => {
    console.log('=== REMOVE BACKGROUND CLICKED ===');
    console.log('Team:', team.name, 'Logo path:', team.logoPath);

    if (!team.logoPath) {
      console.log('ERROR: No logo path found for team');
      toast({
        title: "No Logo Found",
        description: "This team doesn't have a logo to process.",
        variant: "destructive",
      });
      return;
    }

    console.log('Setting processing state...');
    setProcessing(true);
    setSelectedTeam(team.id);
    setOriginalImageUrl(team.logoPath);
    console.log('State set, starting background removal process...');

    try {
      console.log('Step 1: Fetching image from:', team.logoPath);
      const response = await fetch(team.logoPath);
      console.log('Fetch response status:', response.status, 'ok:', response.ok);

      if (!response.ok) {
        throw new Error(`Failed to fetch image: ${response.status}`);
      }

      const blob = await response.blob();
      console.log('Step 2: Got blob, size:', blob.size, 'type:', blob.type);

      // Create File object
      const file = new File([blob], `${team.name}-logo.png`, { 
        type: blob.type || 'image/png' 
      });
      console.log('Step 3: Created file object, size:', file.size);

      // Process the image
      console.log('Step 4: Creating BackgroundRemover...');
      const backgroundRemover = new BackgroundRemover();
      const options: BackgroundRemovalOptions = {
        mode: processingMode,
        tolerance: threshold,
        preserveInternalWhite: true,
        resizeWidth: logoSize
      };

      console.log('Step 5: Starting background removal with options:', options);
      const processedBlob = await backgroundRemover.removeBackground(file, options);
      console.log('Step 6: Background removal completed! Processed size:', processedBlob.size);

      const processedUrl = URL.createObjectURL(processedBlob);
      console.log('Step 7: Generated URL:', processedUrl);

      console.log('Step 8: Setting processed image URL in state...');
      setProcessedImageUrl(processedUrl);
      console.log('Step 9: State updated!');

      toast({
        title: "Background Removed",
        description: `Successfully processed logo for ${team.name}`,
      });

      // Scroll to see the results
      setTimeout(() => {
        document.getElementById('upload-section')?.scrollIntoView({ 
          behavior: 'smooth',
          block: 'start'
        });
      }, 100);

    } catch (error) {
      console.error('=== BACKGROUND REMOVAL ERROR ===');
      console.error('Error details:', error);
      console.error('Error message:', (error as Error).message);
      console.error('Error stack:', (error as Error).stack);

      toast({
        title: "Processing Failed",
        description: `Failed to remove background: ${(error as Error).message || 'Unknown error'}`,
        variant: "destructive",
      });
    } finally {
      console.log('=== CLEANING UP ===');
      setProcessing(false);
      console.log('Processing set to false');
    }
  };

  return (
    <MainLayout 
      title="Logo Management" 
      subtitle="Upload and manage opponent team logos"
    >
      <div className="space-y-8">

        {/* Current Team Logos Section */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Edit3 className="h-5 w-5" />
              Current Team Logos
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
              {oppositionTeams?.map((team) => (
                <div className="space-y-2">
                  <ThemedLogoContainer
                    key={team.id}
                    containerId={`team-logo-${team.id}`}
                    className="border rounded-lg p-3 transition-all"
                    showThemeToggle={true}
                  >
                    <div 
                      onClick={() => handleEditExistingLogo(team)}
                      className="cursor-pointer relative"
                    >
                      <div className="aspect-square border rounded-md mb-2 flex items-center justify-center overflow-hidden bg-inherit">
                        {team.logoPath ? (
                          <img 
                            src={team.logoPath} 
                            alt={`${team.name} logo`}
                            className="max-w-full max-h-full object-contain"
                          />
                        ) : (
                          <div className="text-gray-400 dark:text-gray-500 text-center">
                            <Upload className="h-8 w-8 mx-auto mb-1" />
                            <p className="text-xs">No Logo</p>
                          </div>
                        )}
                      </div>
                      <div className="text-center">
                        <p className="text-sm font-medium truncate">{team.name}</p>
                      </div>
                      <div className="absolute inset-0 rounded-lg transition-all duration-200 flex items-center justify-center">
                        <Edit3 className="h-6 w-6 text-gray-600 dark:text-gray-400 opacity-0 hover:opacity-100 transition-opacity" />
                      </div>
                    </div>
                  </ThemedLogoContainer>

                  {/* Remove Background Button - Completely outside container */}
                  <button 
                    className="w-full text-xs cursor-pointer hover:bg-gray-100 px-2 py-1 border rounded bg-white text-gray-700"
                    onClick={async () => {
                      alert(`Processing ${team.name}...`);
                      await handleRemoveBackground(team);
                    }}
                    data-testid={`button-remove-bg-${team.id}`}
                  >
                    Remove Background
                  </button>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Upload Section */}
        <Card id="upload-section">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Upload className="h-5 w-5" />
              {selectedTeamData ? `Edit Logo: ${selectedTeamData.name}` : 'Upload Team Logo'}
            </CardTitle>
            {selectedTeamData && (
              <p className="text-sm text-gray-600">
                {selectedTeamData.logoPath ? 'Replace existing logo or upload a new image to reprocess' : 'Upload a new logo for this team'}
              </p>
            )}
          </CardHeader>
          <CardContent className="space-y-6">

            {/* Team Selection */}
            <div>
              <label className="block text-sm font-medium mb-2">Select Opponent Team</label>
              <Select value={selectedTeam} onValueChange={setSelectedTeam}>
                <SelectTrigger className="w-full">
                  <SelectValue placeholder="Choose a team..." />
                </SelectTrigger>
                <SelectContent>
                  {oppositionTeams?.map((team) => (
                    <SelectItem key={team.id} value={team.id}>
                      <div className="flex items-center gap-2">
                        {team.logoPath && (
                          <img 
                            src={team.logoPath} 
                            alt={`${team.name} logo`}
                            className="w-4 h-4 object-contain"
                          />
                        )}
                        {team.name}
                        {team.logoPath && <Badge variant="secondary" className="text-xs">Has Logo</Badge>}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Processing Mode Selection */}
            <div>
              <label className="block text-sm font-medium mb-2">Processing Mode</label>
              <div className="flex gap-2 mb-2">
                <Button
                  variant={processingMode === 'smart' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => handleModeChange('smart')}
                  data-testid="button-mode-smart"
                >
                  Smart Mode (Auto)
                </Button>
                <Button
                  variant={processingMode === 'color' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => handleModeChange('color')}
                  data-testid="button-mode-color"
                >
                  Color-Based
                </Button>
                <Button
                  variant={processingMode === 'manual' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => handleModeChange('manual')}
                  data-testid="button-mode-manual"
                >
                  Manual Threshold
                </Button>
              </div>
              {processingMode === 'manual' && (
                <div className="bg-gray-50 p-3 rounded-lg">
                  <div className="flex items-center gap-3 mb-2">
                    <label className="text-sm font-medium">Sensitivity:</label>
                    <Slider
                      value={[threshold]}
                      onValueChange={handleThresholdChange}
                      max={100}
                      min={10}
                      step={5}
                      className="flex-1"
                      data-testid="slider-threshold"
                    />
                    <span className="text-sm font-medium text-blue-600 min-w-[30px]" data-testid="text-threshold">{threshold}</span>
                  </div>
                </div>
              )}
            </div>

            {/* Logo Size Control */}
            <div className="space-y-3">
              <label className="text-sm font-medium">Logo Size (for consistency)</label>
              <div className="flex items-center space-x-4">
                <Slider
                  value={[logoSize]}
                  onValueChange={(value) => {
                    setLogoSize(value[0]);
                    if (selectedFile) processImageWithCurrentSettings(selectedFile);
                  }}
                  min={50}
                  max={400}
                  step={10}
                  className="flex-1"
                  data-testid="slider-logo-size"
                />
                <span className="text-sm text-gray-600 w-16" data-testid="text-logo-size">
                  {logoSize}px
                </span>
              </div>
            </div>

            {/* Theme Toggle */}
            <div className="space-y-3">
              <label className="text-sm font-medium">Preview Theme</label>
              <div className="flex items-center space-x-3">
                <Button
                  variant={!darkMode ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setDarkMode(false)}
                  data-testid="button-light-mode"
                >
                  <Sun className="w-4 h-4 mr-2" />
                  Light
                </Button>
                <Button
                  variant={darkMode ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setDarkMode(true)}
                  data-testid="button-dark-mode"
                >
                  <Moon className="w-4 h-4 mr-2" />
                  Dark
                </Button>
              </div>
            </div>

            {/* File Upload */}
            <div>
              <label className="block text-sm font-medium mb-2">Upload Logo Image</label>
              <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center">
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFileChange}
                  className="hidden"
                  id="logo-upload"
                  data-testid="input-file-upload"
                />
                <label htmlFor="logo-upload" className="cursor-pointer" data-testid="label-file-upload">
                  <Upload className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                  <p className="text-sm text-gray-600 mb-2">
                    Click to upload or drag and drop
                  </p>
                  <p className="text-xs text-gray-500">
                    PNG, JPG, GIF up to 10MB
                  </p>
                </label>
              </div>
            </div>

            {showTip && (
              <div className="bg-blue-50 border border-blue-200 rounded-lg p-3" data-testid="tip-message">
                <div className="flex items-start gap-2">
                  <Info className="h-4 w-4 text-blue-600 mt-0.5 flex-shrink-0" />
                  <div className="text-sm text-blue-800">
                    <strong>💡 Pro Tip:</strong> If the logo has symbols like ™ or ® that still show background, try "Color-Based" mode or adjust the manual threshold. Use the size slider to ensure all logos are consistently sized.
                  </div>
                </div>
              </div>
            )}

            {processing && (
              <div className="text-center py-8">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto mb-4"></div>
                <p className="text-sm text-gray-600">
                  <Wand2 className="inline h-4 w-4 mr-1" />
                  Applying intelligent background removal...
                </p>
              </div>
            )}


            {/* Image Comparison */}
            {(originalImageUrl || processedImageUrl) && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Original Image */}
                {originalImageUrl && (
                  <div className="space-y-2">
                    <h3 className="font-semibold text-center">Original Upload</h3>
                    <div className={`border rounded-lg p-4 ${darkMode ? 'bg-gray-800 border-gray-600' : 'bg-white border-gray-200'}`}>
                      <img 
                        src={originalImageUrl}
                        alt="Original upload"
                        className="w-full h-48 object-contain"
                        data-testid="img-original-logo"
                      />
                    </div>
                    <p className="text-xs text-gray-500 text-center">
                      Original image with background
                    </p>
                  </div>
                )}

                {/* Processed Image */}
                {processedImageUrl && (
                  <div className="space-y-2">
                    <h3 className="font-semibold text-center">Background Removed</h3>
                    <div 
                      className={`border rounded-lg p-4 ${darkMode ? 'border-gray-600' : 'border-gray-200'}`}
                      style={{
                        background: darkMode 
                          ? 'linear-gradient(45deg, #374151 25%, transparent 25%), linear-gradient(-45deg, #374151 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #374151 75%), linear-gradient(-45deg, transparent 75%, #374151 75%)'
                          : 'linear-gradient(45deg, #f0f0f0 25%, transparent 25%), linear-gradient(-45deg, #f0f0f0 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #f0f0f0 75%), linear-gradient(-45deg, transparent 75%, #f0f0f0 75%)',
                        backgroundSize: '20px 20px',
                        backgroundPosition: '0 0, 0 10px, 10px -10px, -10px 0px'
                      }}
                    >
                      <img 
                        src={processedImageUrl}
                        alt="Processed logo"
                        className="w-full h-48 object-contain"
                        data-testid="img-processed-logo"
                      />
                    </div>
                    <p className="text-xs text-gray-500 text-center">
                      Processed PNG with transparent background
                    </p>
                  </div>
                )}
              </div>
            )}

            {/* Save Button */}
            {selectedTeam && processedImageUrl && (
              <div className="flex justify-center pt-4">
                <Button 
                  onClick={handleSave}
                  disabled={saveMutation.isPending}
                  className="flex items-center gap-2"
                  size="lg"
                  data-testid="button-save-logo"
                >
                  {saveMutation.isPending ? (
                    <>
                      <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                      Saving...
                    </>
                  ) : (
                    <>
                      <Save className="h-4 w-4" />
                      Save Logo for {selectedTeamData?.name}
                    </>
                  )}
                </Button>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Current Logos Overview */}
        <Card>
          <CardHeader>
            <CardTitle>Current Team Logos</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {oppositionTeams?.map((team) => (
                <div key={team.id} className={`border rounded-lg p-4 text-center ${darkMode ? 'bg-gray-800 border-gray-600' : 'bg-white border-gray-200'}`}>
                  <div 
                    className="w-16 h-16 mx-auto mb-3 flex items-center justify-center rounded-lg"
                    style={{
                      background: team.logoPath && darkMode
                        ? 'linear-gradient(45deg, #374151 25%, transparent 25%), linear-gradient(-45deg, #374151 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #374151 75%), linear-gradient(-45deg, transparent 75%, #374151 75%)'
                        : team.logoPath 
                          ? 'linear-gradient(45deg, #f0f0f0 25%, transparent 25%), linear-gradient(-45deg, #f0f0f0 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #f0f0f0 75%), linear-gradient(-45deg, transparent 75%, #f0f0f0 75%)'
                          : darkMode ? '#374151' : '#f3f4f6',
                      backgroundSize: team.logoPath ? '12px 12px' : 'auto',
                      backgroundPosition: team.logoPath ? '0 0, 0 6px, 6px -6px, -6px 0px' : 'auto'
                    }}
                  >
                    {team.logoPath ? (
                      <img 
                        src={team.logoPath} 
                        alt={`${team.name} logo`}
                        className="w-full h-full object-contain"
                        data-testid={`img-team-logo-${team.id}`}
                      />
                    ) : (
                      <span className={`text-xs ${darkMode ? 'text-gray-400' : 'text-gray-500'}`}>No Logo</span>
                    )}
                  </div>
                  <h3 className={`font-semibold text-sm ${darkMode ? 'text-white' : 'text-gray-900'}`}>{team.name}</h3>
                  <div className="flex flex-col items-center gap-2">
                    {team.logoPath ? (
                      <Badge className={`${darkMode ? 'bg-green-800 text-green-100' : 'bg-green-100 text-green-800'}`}>
                        <CheckCircle className="h-3 w-3 mr-1" />
                        Has Logo
                      </Badge>
                    ) : (
                      <Badge variant="secondary" className={`${darkMode ? 'bg-gray-600 text-gray-200' : 'bg-gray-200 text-gray-700'}`}>
                        <AlertCircle className="h-3 w-3 mr-1" />
                        Needs Logo
                      </Badge>
                    )}
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleEditExistingLogo(team)}
                      className="text-xs"
                      data-testid={`button-edit-logo-${team.id}`}
                    >
                      <Edit3 className="h-3 w-3 mr-1" />
                      {team.logoPath ? 'Update' : 'Add'} Logo
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>
    </MainLayout>
  );
}

