import express, { type Express } from "express";
import fs from "fs";
import path from "path";
import { createServer as createViteServer, createLogger } from "vite";
import { type Server } from "http";
import viteConfig from "../vite.config";
import { nanoid } from "nanoid";

const viteLogger = createLogger();

export function log(message: string, source = "express") {
  const formattedTime = new Date().toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
    second: "2-digit",
    hour12: true,
  });

  console.log(`${formattedTime} [${source}] ${message}`);
}

export async function setupVite(app: Express, server: Server) {
  const serverOptions = {
    middlewareMode: true,
    hmr: { server },
    allowedHosts: true as const,
  };

  const vite = await createViteServer({
    ...viteConfig,
    configFile: false,
    customLogger: {
      ...viteLogger,
      error: (msg, options) => {
        viteLogger.error(msg, options);
        process.exit(1);
      },
    },
    server: serverOptions,
    appType: "custom",
  });

  app.use(vite.middlewares);
  app.use("*", async (req, res, next) => {
    const url = req.originalUrl;

    try {
      const clientTemplate = path.resolve(
        import.meta.dirname,
        "..",
        "client",
        "index.html",
      );

      // always reload the index.html file from disk incase it changes
      let template = await fs.promises.readFile(clientTemplate, "utf-8");
      template = template.replace(
        `src="/src/main.tsx"`,
        `src="/src/main.tsx?v=${nanoid()}"`,
      );
      const page = await vite.transformIndexHtml(url, template);
      res.status(200).set({ "Content-Type": "text/html" }).end(page);
    } catch (e) {
      vite.ssrFixStacktrace(e as Error);
      next(e);
    }
  });
}

export function serveStatic(app: Express) {
  const distPath = path.resolve(import.meta.dirname, "public");

  if (!fs.existsSync(distPath)) {
    throw new Error(
      `Could not find the build directory: ${distPath}, make sure to build the client first`,
    );
  }

  app.use(express.static(distPath));

  // fall through to index.html if the file doesn't exist
  app.use("*", (_req, res) => {
    res.sendFile(path.resolve(distPath, "index.html"));
  });
}

client/src/components/dialogs/fixture-cr.content:
import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { CalendarIcon, Plus } from "lucide-react";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { format } from "date-fns";
import { useQuery, useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import type { OppositionTeam, Competition } from "@shared/schema";
import { LogoUpload } from "@/components/logo-upload";
import { useToast } from "@/hooks/use-toast";

const fixtureCreateSchema = z.object({
  opponent: z.string().min(1, "Opponent is required"),
  oppositionTeamId: z.string().optional(),
  venue: z.string().optional(),
  date: z.date(),
  timeSlot: z.enum(["MORNING", "AFTERNOON", "EVENING"]),
  kickoffTime: z.string().min(1, "Kick-off time is required"),
  location: z.string().optional(),
  type: z.enum(["HOME", "AWAY"]),
  status: z.enum(["SCHEDULED", "IN_PROGRESS", "COMPLETED", "POSTPONED", "CANCELLED"]).default("SCHEDULED"),
  homeScore: z.coerce.number().optional(),
  awayScore: z.coerce.number().optional(),
  competitionId: z.string().optional(),
  notes: z.string().optional(),
  report: z.string().optional(),
  attendance: z.coerce.number().optional(),
});

const opponentCreateSchema = z.object({
  primaryColor: z.string().min(1, "Primary color is required"),
  secondaryColor: z.string().optional(),
  logoPath: z.string().optional(),
});

type FixtureCreateFormData = z.infer<typeof fixtureCreateSchema>;
type OpponentCreateFormData = z.infer<typeof opponentCreateSchema>;

interface FixtureCreateDialogProps {
  teamId: string;
  clubId?: string;
  onSave: (data: FixtureCreateFormData & { teamId: string }) => void;
  children: React.ReactNode;
}

export function FixtureCreateDialog({ teamId, clubId, onSave, children }: FixtureCreateDialogProps) {
  const { toast } = useToast();
  const [open, setOpen] = useState(false);
  const [activeTab, setActiveTab] = useState("fixture-details");
  const [newCompetitionName, setNewCompetitionName] = useState("");
  const [newOpponentName, setNewOpponentName] = useState("");
  const [showNewOpponentInput, setShowNewOpponentInput] = useState(false);
  const [previousOpponentId, setPreviousOpponentId] = useState<string | undefined>("");

  const { data: oppositionTeams = [] } = useQuery<OppositionTeam[]>({
    queryKey: ["/api/opposition-teams", clubId],
    queryFn: async () => {
      const url = clubId ? `/api/opposition-teams?clubId=${clubId}` : '/api/opposition-teams';
      const res = await fetch(url);
      if (!res.ok) throw new Error('Failed to fetch opposition teams');
      return res.json();
    }
  });

  const { data: competitions = [] } = useQuery<Competition[]>({
    queryKey: ["/api/teams", teamId, "competitions/enabled"],
    enabled: !!teamId,
  });

  const createCompetitionMutation = useMutation({
    mutationFn: async (name: string): Promise<Competition> => {
      const res = await apiRequest("POST", "/api/competitions", { name, clubId });
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/competitions"] });
    },
  });

  const createOpponentMutation = useMutation({
    mutationFn: async (data: OpponentCreateFormData & { name: string }): Promise<OppositionTeam> => {
      const shortName = data.name.substring(0, 3).toUpperCase();
      const res = await apiRequest("POST", "/api/opposition-teams", {
        name: data.name,
        shortName,
        logoPath: data.logoPath || null,
        websiteUrl: "",
        clubId,
        colors: {
          primary: data.primaryColor,
          secondary: data.secondaryColor || "#FFFFFF",
        },
      });
      return res.json();
    },
    onSuccess: (newTeam) => {
      queryClient.invalidateQueries({ queryKey: ["/api/opposition-teams"] });
      form.setValue("oppositionTeamId", newTeam.id);
      form.setValue("opponent", newTeam.name);
      setNewOpponentName("");
      setShowNewOpponentInput(false);
      opponentForm.reset();
      toast({
        title: "Success",
        description: "Opponent created successfully",
      });
    },
  });

  const form = useForm<FixtureCreateFormData>({
    resolver: zodResolver(fixtureCreateSchema),
    defaultValues: {
      opponent: "",
      oppositionTeamId: "",
      venue: "",
      date: new Date(),
      timeSlot: "AFTERNOON" as const,
      kickoffTime: "15:00",
      location: "",
      type: "HOME",
      status: "SCHEDULED",
      homeScore: undefined,
      awayScore: undefined,
      competitionId: "",
      notes: "",
      report: "",
      attendance: undefined,
    },
  });

  const opponentForm = useForm<OpponentCreateFormData>({
    resolver: zodResolver(opponentCreateSchema),
    defaultValues: {
      primaryColor: "#000000",
      secondaryColor: "#FFFFFF",
      logoPath: "",
    },
  });


  const handleSubmit = async (data: FixtureCreateFormData) => {
    try {
      if (data.competitionId === "__new__") {
        if (!newCompetitionName.trim()) {
          toast({
            title: "Error",
            description: "Please enter a competition name",
            variant: "destructive",
          });
          return;
        }
        const newCompetition = await createCompetitionMutation.mutateAsync(newCompetitionName);
        data.competitionId = newCompetition.id;
      }
      if (!data.competitionId || data.competitionId === "" || data.competitionId === "__none__") {
        data.competitionId = undefined;
      }

      if (showNewOpponentInput) {
        if (!newOpponentName.trim()) {
          toast({
            title: "Error",
            description: "Please enter an opponent name",
            variant: "destructive",
          });
          return;
        }
        const opponentData = opponentForm.getValues();
        const newTeam = await createOpponentMutation.mutateAsync({ ...opponentData, name: newOpponentName });
        data.oppositionTeamId = newTeam.id;
        data.opponent = newTeam.name;
      }

      if (!data.oppositionTeamId || data.oppositionTeamId === "pending") {
        toast({
          title: "Error",
          description: "Please select an opponent",
          variant: "destructive",
        });
        return;
      }

      const [hours, minutes] = data.kickoffTime.split(':').map(Number);
      const updatedDate = new Date(data.date);
      updatedDate.setHours(hours, minutes, 0, 0);

      const formattedData = {
        ...data,
        date: updatedDate,
        venue: data.location || "",
      };

      onSave({ ...formattedData, teamId });

      setOpen(false);
      form.reset();
      setNewCompetitionName("");
      setNewOpponentName("");
      setShowNewOpponentInput(false);
    } catch (error) {
      toast({
        title: "Error",
        description: "Failed to create fixture. Please try again.",
        variant: "destructive",
      });
    }
  };

  const handleOpponentSubmit = (data: OpponentCreateFormData) => {
    if (!newOpponentName.trim()) {
      toast({
        title: "Error",
        description: "Opponent name is required",
        variant: "destructive",
      });
      return;
    }
    createOpponentMutation.mutate({ ...data, name: newOpponentName });
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        {children}
      </DialogTrigger>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Add New Fixture</DialogTitle>
          <DialogDescription>
            Schedule a new match against an opposition team.
          </DialogDescription>
        </DialogHeader>

        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsContent value="fixture-details">
            <Form {...form}>
              <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-4">
                {/* Row 1: Competition, Match Type */}
                <div className="grid grid-cols-[1fr_200px] gap-4">
                  <FormField
                    control={form.control}
                    name="competitionId"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Competition</FormLabel>
                        <FormControl>
                          <div className="flex gap-2">
                            {field.value === "__new__" ? (
                              <>
                                <Input 
                                  value={newCompetitionName}
                                  onChange={(e) => setNewCompetitionName(e.target.value)}
                                  placeholder="Enter new competition name" 
                                  data-testid="input-new-competition"
                                  className="flex-1"
                                />
                                <Button
                                  type="button"
                                  variant="outline"
                                  size="sm"
                                  onClick={() => {
                                    field.onChange("");
                                    setNewCompetitionName("");
                                  }}
                                  data-testid="button-cancel-new-competition"
                                >
                                  Cancel
                                </Button>
                              </>
                            ) : (
                              <>
                                <Select
                                  value={field.value || ""}
                                  onValueChange={field.onChange}
                                  data-testid="select-competition"
                                >
                                  <SelectTrigger className="flex-1">
                                    <SelectValue placeholder="Select competition" />
                                  </SelectTrigger>
                                  <SelectContent>
                                    <SelectItem value="__none__">None</SelectItem>
                                    {competitions.map((comp) => (
                                      <SelectItem key={comp.id} value={comp.id}>
                                        {comp.name}
                                      </SelectItem>
                                    ))}
                                  </SelectContent>
                                </Select>
                                <Button
                                  type="button"
                                  variant="outline"
                                  size="icon"
                                  onClick={() => field.onChange("__new__")}
                                  data-testid="button-add-competition"
                                >
                                  <Plus className="h-4 w-4" />
                                </Button>
                              </>
                            )}
                          </div>
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="type"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Match Type</FormLabel>
                        <Select onValueChange={field.onChange} defaultValue={field.value}>
                          <FormControl>
                            <SelectTrigger data-testid="select-new-type">
                              <SelectValue placeholder="Select type" />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            <SelectItem value="HOME">Home</SelectItem>
                            <SelectItem value="AWAY">Away</SelectItem>
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>

                {/* Row 2: Opposition */}
                <FormField
                  control={form.control}
                  name="oppositionTeamId"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Opposition</FormLabel>
                      <FormControl>
                        <div className="flex gap-2">
                          {showNewOpponentInput ? (
                            <Input 
                              value={newOpponentName}
                              onChange={(e) => setNewOpponentName(e.target.value)}
                              placeholder="Enter opponent name" 
                              data-testid="input-new-opponent-name"
                              className="flex-1"
                            />
                          ) : (
                            <>
                              <Select
                                value={field.value || ""}
                                onValueChange={(value) => {
                                  if (value === "__new__") {
                                    setPreviousOpponentId(field.value);
                                    setShowNewOpponentInput(true);
                                  } else {
                                    setShowNewOpponentInput(false);
                                    field.onChange(value);
                                    const selectedTeam = oppositionTeams.find(team => team.id === value);
                                    if (selectedTeam) {
                                      form.setValue("opponent", selectedTeam.name);
                                      opponentForm.setValue("logoPath", selectedTeam.logoPath || "");
                                      opponentForm.setValue("primaryColor", selectedTeam.colors?.primary || "#000000");
                                      opponentForm.setValue("secondaryColor", selectedTeam.colors?.secondary || "#FFFFFF");
                                    }
                                  }
                                }}
                                data-testid="select-opponent"
                              >
                                <SelectTrigger className="flex-1">
                                  <SelectValue placeholder="Select opponent" />
                                </SelectTrigger>
                                <SelectContent>
                                  {oppositionTeams.filter((team) => team.isVisible !== false).map((team) => (
                                    <SelectItem key={team.id} value={team.id}>
                                      <div className="flex items-center gap-2">
                                        {team.logoPath ? (
                                          <img 
                                            src={team.logoPath} 
                                            alt={`${team.name} logo`}
                                            className="w-4 h-4 object-cover rounded"
                                          />
                                        ) : (
                                          <div className="w-4 h-4 bg-muted rounded flex items-center justify-center text-xs">
                                            {team.shortName}
                                          </div>
                                        )}
                                        {team.name}
                                      </div>
                                    </SelectItem>
                                  ))}
                                </SelectContent>
                              </Select>
                              <Button
                                type="button"
                                variant="outline"
                                size="icon"
                                onClick={() => {
                                  setPreviousOpponentId(field.value);
                                  setShowNewOpponentInput(true);
                                }}
                                data-testid="button-add-opponent"
                              >
                                <Plus className="h-4 w-4" />
                              </Button>
                            </>
                          )}
                        </div>
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Row 3: Date, Time Slot, Kick-off Time */}
                <div className="grid grid-cols-3 gap-4">
                  <FormField
                    control={form.control}
                    name="date"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Date</FormLabel>
                        <Popover>
                          <PopoverTrigger asChild>
                            <FormControl>
                              <Button
                                variant={"outline"}
                                className={cn(
                                  "w-full pl-3 text-left font-normal h-10",
                                  !field.value && "text-muted-foreground"
                                )}
                                data-testid="button-new-date-picker"
                              >
                                {field.value ? (
                                  format(field.value, "d MMM yyyy")
                                ) : (
                                  <span>Pick a date</span>
                                )}
                                <CalendarIcon className="ml-auto h-4 w-4 opacity-50" />
                              </Button>
                            </FormControl>
                          </PopoverTrigger>
                          <PopoverContent className="w-auto p-0" align="start">
                            <Input
                              type="date"
                              value={field.value ? format(field.value, "yyyy-MM-dd") : ""}
                              onChange={(e) => {
                                const selectedDate = new Date(e.target.value + 'T12:00:00');
                                field.onChange(selectedDate);
                              }}
                              data-testid="input-new-date"
                            />
                          </PopoverContent>
                        </Popover>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="timeSlot"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Time Slot</FormLabel>
                        <Select 
                          onValueChange={(value) => {
                            field.onChange(value);
                            const timeMapping = {
                              MORNING: "10:00",
                              AFTERNOON: "15:00", 
                              EVENING: "20:00"
                            };
                            form.setValue("kickoffTime", timeMapping[value as keyof typeof timeMapping]);
                          }} 
                          defaultValue={field.value}
                        >
                          <FormControl>
                            <SelectTrigger data-testid="select-time-slot">
                              <SelectValue placeholder="Select time slot" />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            <SelectItem value="MORNING">Morning</SelectItem>
                            <SelectItem value="AFTERNOON">Afternoon</SelectItem>
                            <SelectItem value="EVENING">Evening</SelectItem>
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="kickoffTime"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Kick-off Time</FormLabel>
                        <FormControl>
                          <Input 
                            {...field} 
                            type="time" 
                            data-testid="input-kickoff-time"
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>

                {/* Row 4: Status, Home Score, Away Score */}
                <div className="grid grid-cols-3 gap-4">
                  <FormField
                    control={form.control}
                    name="status"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Status</FormLabel>
                        <Select onValueChange={field.onChange} defaultValue={field.value}>
                          <FormControl>
                            <SelectTrigger data-testid="select-status">
                              <SelectValue placeholder="Select status" />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            <SelectItem value="SCHEDULED">Scheduled</SelectItem>
                            <SelectItem value="IN_PROGRESS">In Progress</SelectItem>
                            <SelectItem value="COMPLETED">Completed</SelectItem>
                            <SelectItem value="POSTPONED">Postponed</SelectItem>
                            <SelectItem value="CANCELLED">Cancelled</SelectItem>
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="homeScore"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Home Score</FormLabel>
                        <FormControl>
                          <Input 
                            {...field} 
                            type="number" 
                            placeholder="-"
                            value={field.value ?? ""}
                            onChange={(e) => field.onChange(e.target.value === "" ? undefined : parseInt(e.target.value))}
                            data-testid="input-home-score"
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="awayScore"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Away Score</FormLabel>
                        <FormControl>
                          <Input 
                            {...field} 
                            type="number" 
                            placeholder="-"
                            value={field.value ?? ""}
                            onChange={(e) => field.onChange(e.target.value === "" ? undefined : parseInt(e.target.value))}
                            data-testid="input-away-score"
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>


                {/* Hidden opponent name field */}
                <FormField
                  control={form.control}
                  name="opponent"
                  render={({ field }) => (
                    <input type="hidden" {...field} />
                  )}
                />

                {/* Hidden fields for form compatibility */}
                <FormField
                  control={form.control}
                  name="location"
                  render={({ field }) => (
                    <input type="hidden" {...field} value="" />
                  )}
                />

                <FormField
                  control={form.control}
                  name="venue"
                  render={({ field }) => (
                    <input type="hidden" {...field} value="" />
                  )}
                />

                <div className="space-y-6 pt-6">
                  <Form {...opponentForm}>
                    {/* Opposition Colors Section */}
                    <div className="space-y-4">
                      <div className="border-b pb-2">
                        <h4 className="text-sm font-semibold">Opposition Colors</h4>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                        <FormField
                          control={opponentForm.control}
                          name="primaryColor"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Primary Color</FormLabel>
                              <FormControl>
                                <div className="flex gap-2 items-center">
                                  <Input 
                                    {...field} 
                                    type="color" 
                                    className="h-10 w-16 cursor-pointer p-1"
                                    data-testid="input-opponent-primary-color"
                                  />
                                  <Input 
                                    value={field.value}
                                    onChange={(e) => field.onChange(e.target.value)}
                                    placeholder="#000000"
                                    className="flex-1 font-mono text-sm"
                                  />
                                </div>
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />

                        <FormField
                          control={opponentForm.control}
                          name="secondaryColor"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Secondary Color</FormLabel>
                              <FormControl>
                                <div className="flex gap-2 items-center">
                                  <Input 
                                    {...field} 
                                    type="color" 
                                    className="h-10 w-16 cursor-pointer p-1"
                                    data-testid="input-opponent-secondary-color"
                                  />
                                  <Input 
                                    value={field.value}
                                    onChange={(e) => field.onChange(e.target.value)}
                                    placeholder="#FFFFFF"
                                    className="flex-1 font-mono text-sm"
                                  />
                                </div>
                              </FormControl>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>
                    </div>

                    {/* Team Logo Section */}
                    <div className="space-y-4">
                      <div className="border-b pb-2">
                        <h4 className="text-sm font-semibold">Team Logo</h4>
                      </div>

                      <FormField
                        control={opponentForm.control}
                        name="logoPath"
                        render={({ field }) => (
                          <FormItem>
                            <FormControl>
                              <LogoUpload
                                teamName={showNewOpponentInput ? (newOpponentName || "Opponent") : (oppositionTeams.find(t => t.id === form.watch("oppositionTeamId"))?.name || "Opponent")}
                                currentLogo={field.value}
                                onUploadComplete={(logoPath: string) => {
                                  field.onChange(logoPath);
                                  toast({
                                    title: "Logo Uploaded",
                                    description: "Logo has been uploaded successfully",
                                  });
                                }}
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>
                  </Form>
                </div>

                <div className="flex justify-end gap-2 pt-4">
                  <Button 
                    type="button" 
                    variant="outline" 
                    onClick={() => setOpen(false)}
                    data-testid="button-cancel"
                  >
                    Cancel
                  </Button>
                  <Button 
                    type="button"
                    data-testid="button-save-fixture"
                    disabled={createCompetitionMutation.isPending || createOpponentMutation.isPending}
                    onClick={() => {
                      if (showNewOpponentInput && newOpponentName.trim()) {
                        form.setValue("opponent", newOpponentName.trim());
                        form.setValue("oppositionTeamId", "pending");
                      }
                      form.handleSubmit(handleSubmit)();
                    }}
                  >
                    {createCompetitionMutation.isPending || createOpponentMutation.isPending ? "Creating..." : "Create Fixture"}
                  </Button>
                </div>
              </form>
            </Form>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}

client/src/components/possession-chart.t.content:
interface PossessionChartProps {
  teamName: string;
  opponentName: string;
  teamPossession: number;
  opponentPossession: number;
}

export function PossessionChart({ teamName, opponentName, teamPossession, opponentPossession }: PossessionChartProps) {
  // Ensure percentages add up to 100
  const totalPossession = teamPossession + opponentPossession;
  const normalizedTeamPossession = totalPossession > 0 ? (teamPossession / totalPossession) * 100 : 50;
  const normalizedOpponentPossession = 100 - normalizedTeamPossession;

  return (
    <div className="space-y-3">
      <h4 className="font-semibold text-center">Ball Possession</h4>

      {/* Horizontal bar chart */}
      <div className="relative w-full h-12 bg-gray-200 rounded-lg overflow-hidden">
        {/* Team side (left) */}
        <div 
          className="absolute left-0 top-0 h-full bg-red-500 transition-all duration-500 ease-out"
          style={{ width: `${normalizedTeamPossession}%` }}
        />

        {/* Opponent side (right) */}
        <div 
          className="absolute right-0 top-0 h-full bg-blue-500 transition-all duration-500 ease-out"
          style={{ width: `${normalizedOpponentPossession}%` }}
        />

        {/* Center divider line */}
        <div className="absolute left-1/2 top-0 h-full w-0.5 bg-white transform -translate-x-0.5 z-10" />
      </div>

      {/* Labels and percentages */}
      <div className="flex justify-between items-center">
        <div className="text-left">
          <div className="font-semibold text-red-600">{teamName}</div>
          <div className="text-2xl font-bold">{teamPossession}%</div>
        </div>

        <div className="text-center text-muted-foreground text-sm">
          vs
        </div>

        <div className="text-right">
          <div className="font-semibold text-blue-600">{opponentName}</div>
          <div className="text-2xl font-bold">{opponentPossession}%</div>
        </div>
      </div>
    </div>
  );
}

