// Quick Player Add Component
function QuickPlayerAdd({ onPlayersAdded }: { onPlayersAdded: () => void }) {
  const { toast } = useToast();
  const [quickText, setQuickText] = useState("");
  const [selectedTeamId, setSelectedTeamId] = useState("");
  const [isAdding, setIsAdding] = useState(false);
  const [showReviewModal, setShowReviewModal] = useState(false);
  const [parsedPlayers, setParsedPlayers] = useState<Array<{
    name: string;
    firstName: string;
    lastName: string;
    position: string;
    jerseyNumber: string;
  }>>([]);

  // Fetch teams for selection
  const { data: teams } = useQuery({
    queryKey: ["/api/teams"]
  });

  const handleQuickAdd = async () => {
    if (!quickText.trim()) {
      toast({
        title: "Missing Information",
        description: "Please enter player names.",
        variant: "destructive",
      });
      return;
    }

    // Parse the text into players - handle scraped format
    const lines = quickText.split('\n').filter(line => line.trim());
    const players = [];
    let currentPosition = 'Unknown';
    let i = 0;

    console.log('Parsing lines:', lines);

    while (i < lines.length) {
      const trimmed = lines[i].trim();

      // Skip empty lines
      if (!trimmed) {
        i++;
        continue;
      }

      // Check if this line is a position header
      const lowerLine = trimmed.toLowerCase();
      if (lowerLine.includes('goalkeeper') || lowerLine.includes('keeper')) {
        currentPosition = 'Goalkeeper';
        console.log('Set position to Goalkeeper');
        i++;
        continue;
      } else if (lowerLine.includes('defender') || lowerLine.includes('defence')) {
        currentPosition = 'Defender';
        console.log('Set position to Defender');
        i++;
        continue;
      } else if (lowerLine.includes('midfielder') || lowerLine.includes('midfield')) {
        currentPosition = 'Midfielder';
        console.log('Set position to Midfielder');
        i++;
        continue;
      } else if (lowerLine.includes('forward') || lowerLine.includes('striker') || lowerLine.includes('attacker')) {
        currentPosition = 'Forward';
        console.log('Set position to Forward');
        i++;
        continue;
      }

      // Check if this looks like a player name (contains letters and possibly dots/initials)
      if (trimmed.match(/^[A-Za-z][A-Za-z\s\.\-\']+$/)) {
        let playerName = trimmed;
        let age = null;

        // Look ahead for age pattern
        let j = i + 1;
        while (j < lines.length && j < i + 4) { // Look ahead max 4 lines
          const nextLine = lines[j].trim();
          if (nextLine.includes('years old')) {
            // Extract age
            const ageMatch = nextLine.match(/(\d+)\s*years old/);
            if (ageMatch) {
              age = parseInt(ageMatch[1]);
            }
            break;
          } else if (nextLine.toLowerCase().includes('goalkeeper') || 
                     nextLine.toLowerCase().includes('defender') || 
                     nextLine.toLowerCase().includes('midfielder') || 
                     nextLine.toLowerCase().includes('forward') ||
                     nextLine.toLowerCase().includes('striker')) {
            // Hit next position, stop looking
            break;
          }
          j++;
        }

        // Parse name into first/last
        const nameParts = playerName.split(/\s+/);
        const firstName = nameParts[0] || playerName;
        const lastName = nameParts.slice(1).join(' ') || '';

        players.push({
          name: playerName,
          firstName,
          lastName,
          position: currentPosition,
          jerseyNumber: '',
          age
        });
        console.log(`Added player: ${playerName} (${currentPosition}, age: ${age})`);

        // Skip ahead past the stats/age lines we've processed
        i = j;
      } else {
        i++;
      }
    }

    if (players.length === 0) {
      toast({
        title: "No Players Found",
        description: "Please enter player names (one per line).",
        variant: "destructive",
      });
      return;
    }

    // Show review modal instead of immediately importing
    setParsedPlayers(players);
    setShowReviewModal(true);
  };

  const handleConfirmImport = async () => {
    if (!selectedTeamId) {
      toast({
        title: "Missing Team",
        description: "Please select a team to add players to.",
        variant: "destructive",
      });
      return;
    }

    setIsAdding(true);
    try {
      // Convert parsed players back to the expected format
      const playersToImport = parsedPlayers.map(p => ({
        name: `${p.firstName} ${p.lastName}`.trim(),
        position: p.position,
        age: null,
        appearances: 0,
        goals: 0,
        jerseyNumber: p.jerseyNumber ? parseInt(p.jerseyNumber) : null
      }));

      const response = await fetch("/api/squad/bulk-import", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          teamId: selectedTeamId,
          players: playersToImport
        }),
      });

      const result = await response.json();

      if (result.success) {
        toast({
          title: "Players Added!",
          description: `Successfully added ${result.imported} players to the team.`,
        });

        setQuickText("");
        setShowReviewModal(false);
        setParsedPlayers([]);
        onPlayersAdded();
      } else {
        throw new Error(result.message || "Import failed");
      }
    } catch (error) {
      toast({
        title: "Import Failed",
        description: "Failed to add players. Please try again.",
        variant: "destructive",
      });
    } finally {
      setIsAdding(false);
    }
  };

  return (
    <div className="space-y-4">

      {/* Review Modal */}
      <Dialog open={showReviewModal} onOpenChange={setShowReviewModal}>
        <DialogContent className="max-w-4xl max-h-[80vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Review Players Before Adding</DialogTitle>
            <DialogDescription>
              Review and edit player details before adding them to your team.
            </DialogDescription>
          </DialogHeader>

          {/* Team Selection */}
          <div className="space-y-2 mb-4">
            <label className="text-sm font-medium">Add to Team</label>
            <Select value={selectedTeamId} onValueChange={setSelectedTeamId}>
              <SelectTrigger>
                <SelectValue placeholder="Select a team..." />
              </SelectTrigger>
              <SelectContent>
                {teams?.map((team: any) => (
                  <SelectItem key={team.id} value={team.id}>
                    {team.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Players Table */}
          <div className="border rounded-lg overflow-hidden">
            <table className="w-full">
              <thead className="bg-muted">
                <tr>
                  <th className="p-3 text-left text-sm font-medium">Jersey #</th>
                  <th className="p-3 text-left text-sm font-medium">First Name</th>
                  <th className="p-3 text-left text-sm font-medium">Last Name</th>
                  <th className="p-3 text-left text-sm font-medium">Position</th>
                </tr>
              </thead>
              <tbody>
                {parsedPlayers.map((player, index) => (
                  <tr key={index} className="border-t">
                    <td className="p-3">
                      <Input
                        value={player.jerseyNumber}
                        onChange={(e) => {
                          const updated = [...parsedPlayers];
                          updated[index].jerseyNumber = e.target.value;
                          setParsedPlayers(updated);
                        }}
                        placeholder="#"
                        className="w-16"
                      />
                    </td>
                    <td className="p-3">
                      <Input
                        value={player.firstName}
                        onChange={(e) => {
                          const updated = [...parsedPlayers];
                          updated[index].firstName = e.target.value;
                          setParsedPlayers(updated);
                        }}
                        placeholder="First name"
                      />
                    </td>
                    <td className="p-3">
                      <Input
                        value={player.lastName}
                        onChange={(e) => {
                          const updated = [...parsedPlayers];
                          updated[index].lastName = e.target.value;
                          setParsedPlayers(updated);
                        }}
                        placeholder="Last name"
                      />
                    </td>
                    <td className="p-3">
                      <Select
                        value={player.position}
                        onValueChange={(value) => {
                          const updated = [...parsedPlayers];
                          updated[index].position = value;
                          setParsedPlayers(updated);
                        }}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="Goalkeeper">Goalkeeper</SelectItem>
                          <SelectItem value="Defender">Defender</SelectItem>
                          <SelectItem value="Midfielder">Midfielder</SelectItem>
                          <SelectItem value="Forward">Forward</SelectItem>
                        </SelectContent>
                      </Select>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowReviewModal(false)}
            >
              Cancel
            </Button>
            <Button
              onClick={handleConfirmImport}
              disabled={isAdding || !selectedTeamId}
            >
              {isAdding ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Adding Players...
                </>
              ) : (
                <>
                  <Users className="mr-2 h-4 w-4" />
                  Add {parsedPlayers.length} Players to Team
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// Squad Import Interface Component
function SquadImportInterface() {
  const { toast } = useToast();
  const [importUrl, setImportUrl] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [previewData, setPreviewData] = useState<{
    players: Array<{
      name: string;
      position: string;
      age: number | null;
      appearances: number;
      goals: number;
    }>;
    playersFound: number;
    url: string;
  } | null>(null);
  const [selectedPlayers, setSelectedPlayers] = useState<Set<string>>(new Set());
  const [selectedTeamId, setSelectedTeamId] = useState("");
  const [importing, setImporting] = useState(false);

  // Fetch teams for selection
  const { data: teams } = useQuery({
    queryKey: ["/api/teams"]
  });

  const handleFetchSquad = async () => {
    if (!importUrl.trim()) {
      toast({
        title: "URL Required",
        description: "Please enter a URL to import squad from.",
        variant: "destructive",
      });
      return;
    }

    setIsLoading(true);
    try {
      const response = await fetch("/api/squad/import-from-url", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          url: importUrl.trim()
        }),
      });

      const result = await response.json();

      if (result.success && result.players.length > 0) {
        setPreviewData(result);
        // Select all players by default
        setSelectedPlayers(new Set(result.players.map((p: any) => p.name)));
        toast({
          title: "Squad Found!",
          description: `Found ${result.playersFound} players. Review and select which ones to import.`,
        });
      } else {
        toast({
          title: "No Players Found",
          description: "Could not find any player data on this page. Try a different URL or format.",
          variant: "destructive",
        });
      }
    } catch (error) {
      console.error("Import error:", error);
      toast({
        title: "Import Failed",
        description: "Failed to import squad from URL. Please check the URL and try again.",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleImportSelected = async () => {
    if (!previewData || selectedPlayers.size === 0) {
      toast({
        title: "No Players Selected",
        description: "Please select at least one player to import.",
        variant: "destructive",
      });
      return;
    }

    if (!selectedTeamId) {
      toast({
        title: "Team Required",
        description: "Please select a team to import players to.",
        variant: "destructive",
      });
      return;
    }

    setImporting(true);
    try {
      const selectedPlayerData = previewData.players.filter(p => 
        selectedPlayers.has(p.name)
      );

      const response = await fetch("/api/squad/bulk-import", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          teamId: selectedTeamId,
          players: selectedPlayerData
        }),
      });

      const result = await response.json();

      if (result.success) {
        toast({
          title: "Import Successful!",
          description: `Successfully imported ${result.imported} players to the team.`,
        });

        // Reset the form
        setPreviewData(null);
        setSelectedPlayers(new Set());
        setImportUrl("");
        setSelectedTeamId("");

        // Refresh the teams data
        queryClient.invalidateQueries({ queryKey: ["/api/teams"] });
        queryClient.invalidateQueries({ queryKey: ["/api/users"] });
        // Invalidate team-specific squad queries
        queryClient.invalidateQueries({ queryKey: ["/api/team"] });
      }
    } catch (error) {
      console.error("Bulk import error:", error);
      toast({
        title: "Import Failed",
        description: "Failed to import players. Please try again.",
        variant: "destructive",
      });
    } finally {
      setImporting(false);
    }
  };

  const togglePlayerSelection = (playerName: string) => {
    const newSelection = new Set(selectedPlayers);
    if (newSelection.has(playerName)) {
      newSelection.delete(playerName);
    } else {
      newSelection.add(playerName);
    }
    setSelectedPlayers(newSelection);
  };

  const selectAll = () => {
    if (previewData) {
      setSelectedPlayers(new Set(previewData.players.map(p => p.name)));
    }
  };

  const selectNone = () => {
    setSelectedPlayers(new Set());
  };

  return (
    <div className="space-y-6">
      {/* URL Import Section */}
      <div className="space-y-4">
        <div className="space-y-2">
          <label className="text-sm font-medium">Import from URL</label>
          <div className="flex space-x-2">
            <Input
              placeholder="Paste squad URL here... (e.g. https://uk.soccerway.com/teams/.../squad/)"
              value={importUrl}
              onChange={(e) => setImportUrl(e.target.value)}
              className="flex-1"
              data-testid="input-import-url"
            />
            <Button 
              onClick={handleFetchSquad}
              disabled={isLoading || !importUrl.trim()}
              data-testid="button-fetch-squad"
            >
              {isLoading ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Fetching...
                </>
              ) : (
                <>
                  <ExternalLink className="mr-2 h-4 w-4" />
                  Review Players
                </>
              )}
            </Button>
          </div>
          <p className="text-xs text-muted-foreground">
            Some sites with dynamic content may not work.
          </p>
        </div>
      </div>

      {/* Manual Quick Add Section */}
      <div className="border-t pt-4">
        <QuickPlayerAdd onPlayersAdded={() => {
          // Refresh teams data
          queryClient.invalidateQueries({ queryKey: ["/api/teams"] });
          queryClient.invalidateQueries({ queryKey: ["/api/users"] });
        }} />
      </div>

      {/* Preview Section */}
      {previewData && (
        <div className="space-y-4 p-4 border rounded-lg bg-muted/50">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="font-semibold">Squad Preview</h3>
              <p className="text-sm text-muted-foreground">
                Found {previewData.playersFound} players from {new URL(previewData.url).hostname}
              </p>
            </div>
            <div className="space-x-2">
              <Button variant="outline" size="sm" onClick={selectAll}>
                Select All
              </Button>
              <Button variant="outline" size="sm" onClick={selectNone}>
                Select None
              </Button>
            </div>
          </div>

          {/* Team Selection */}
          <div className="space-y-2">
            <label className="text-sm font-medium">Import to Team</label>
            <Select value={selectedTeamId} onValueChange={setSelectedTeamId}>
              <SelectTrigger>
                <SelectValue placeholder="Select a team..." />
              </SelectTrigger>
              <SelectContent>
                {teams?.map((team: any) => (
                  <SelectItem key={team.id} value={team.id}>
                    {team.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Players List */}
          <div className="space-y-2 max-h-60 overflow-y-auto">
            <p className="text-sm font-medium">
              Players ({selectedPlayers.size} of {previewData.players.length} selected)
            </p>

            {/* Headers */}
            <div className="grid grid-cols-5 gap-2 px-2 py-1 text-xs font-medium text-muted-foreground border-b">
              <div>Number</div>
              <div>First Name</div>
              <div>Last Name</div>
              <div>Position</div>
              <div>Age</div>
            </div>

            <div className="grid gap-2">
              {previewData.players.map((player, index) => (
                <div
                  key={index}
                  className={`flex items-center space-x-3 p-2 rounded border cursor-pointer transition-colors ${
                    selectedPlayers.has(player.name)
                      ? 'bg-primary/10 border-primary'
                      : 'bg-background hover:bg-muted/50'
                  }`}
                  onClick={() => togglePlayerSelection(player.name)}
                >
                  <div className="w-4 h-4 flex items-center justify-center">
                    {selectedPlayers.has(player.name) && (
                      <CheckCircle className="h-4 w-4 text-primary" />
                    )}
                  </div>

                  <div className="flex-1 grid grid-cols-5 gap-2 text-sm">
                    <div className="text-muted-foreground">
                      #{player.jerseyNumber || 'N/A'}
                    </div>
                    <div className="font-medium">
                      {player.name.split(' ')[0] || player.name}
                    </div>
                    <div className="font-medium">
                      {player.name.split(' ').slice(1).join(' ') || ''}
                    </div>
                    <div className="text-muted-foreground">{player.position}</div>
                    <div className="text-muted-foreground">
                      {player.age ? `${player.age}` : 'N/A'}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Import Button */}
          <Button 
            onClick={handleImportSelected}
            disabled={importing || selectedPlayers.size === 0 || !selectedTeamId}
            className="w-full"
            data-testid="button-import-selected"
          >
            {importing ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Importing {selectedPlayers.size} players...
              </>
            ) : (
              <>
                <Users className="mr-2 h-4 w-4" />
                Import {selectedPlayers.size} Selected Players
              </>
            )}
          </Button>
        </div>
      )}
    </div>
  );
}

// Fixtures Import Interface Component
function FixturesImportInterface() {
  const { toast } = useToast();
  const [importUrl, setImportUrl] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [previewData, setPreviewData] = useState<{
    fixtures: Array<{
      date: string;
      time: string;
      homeTeam: string;
      awayTeam: string;
      userTeam: string;
      isHome: boolean;
    }>;
    url: string;
  } | null>(null);
  const [selectedFixtures, setSelectedFixtures] = useState<Set<string>>(new Set());
  const [selectedTeamId, setSelectedTeamId] = useState("");
  const [importing, setImporting] = useState(false);

  // Fetch teams for selection
  const { data: teams } = useQuery({
    queryKey: ["/api/teams"]
  });

  const handleFetchFixtures = async () => {
    if (!importUrl.trim()) {
      toast({
        title: "URL Required",
        description: "Please enter a URL to import fixtures from.",
        variant: "destructive",
      });
      return;
    }

    setIsLoading(true);
    try {
      const response = await fetch("/api/fixtures/import-from-url", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          url: importUrl.trim()
        }),
      });

      const result = await response.json();

      if (result.success && result.fixtures.length > 0) {
        setPreviewData(result);
        // Select all fixtures by default
        const fixtureKeys = result.fixtures.map((f: any, index: number) => 
          `${f.homeTeam}-${f.awayTeam}-${f.date}-${index}`
        );
        setSelectedFixtures(new Set(fixtureKeys));
        toast({
          title: "Fixtures Found!",
          description: `Found ${result.fixtures.length} fixtures. Review and select which ones to import.`,
        });
      } else {
        toast({
          title: "No Fixtures Found",
          description: "Could not find any fixture data on this page. Try a different URL or format.",
          variant: "destructive",
        });
      }
    } catch (error) {
      console.error("Import error:", error);
      toast({
        title: "Import Failed",
        description: "Failed to import fixtures from URL. Please check the URL and try again.",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleImportSelected = async () => {
    if (!previewData || selectedFixtures.size === 0) {
      toast({
        title: "No Fixtures Selected",
        description: "Please select at least one fixture to import.",
        variant: "destructive",
      });
      return;
    }

    if (!selectedTeamId) {
      toast({
        title: "Team Required",
        description: "Please select a team to import fixtures to.",
        variant: "destructive",
      });
      return;
    }

    setImporting(true);
    try {
      const selectedFixtureData = previewData.fixtures.filter((f, index) => {
        const key = `${f.homeTeam}-${f.awayTeam}-${f.date}-${index}`;
        return selectedFixtures.has(key);
      });

      const response = await fetch("/api/fixtures/bulk-import", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          teamId: selectedTeamId,
          fixtures: selectedFixtureData
        }),
      });

      const result = await response.json();

      if (result.success) {
        toast({
          title: "Import Successful!",
          description: `Successfully imported ${result.imported} fixtures to the team.`,
        });

        // Reset the form
        setPreviewData(null);
        setSelectedFixtures(new Set());
        setImportUrl("");
        setSelectedTeamId("");

        // Refresh the data
        queryClient.invalidateQueries({ queryKey: ["/api/teams"] });
        queryClient.invalidateQueries({ queryKey: ["/api/fixtures"] });
      }
    } catch (error) {
      console.error("Bulk import error:", error);
      toast({
        title: "Import Failed",
        description: "Failed to import fixtures. Please try again.",
        variant: "destructive",
      });
    } finally {
      setImporting(false);
    }
  };

  const toggleFixtureSelection = (fixtureKey: string) => {
    const newSelection = new Set(selectedFixtures);
    if (newSelection.has(fixtureKey)) {
      newSelection.delete(fixtureKey);
    } else {
      newSelection.add(fixtureKey);
    }
    setSelectedFixtures(newSelection);
  };

  const toggleSelectAll = () => {
    if (!previewData) return;

    if (selectedFixtures.size === previewData.fixtures.length) {
      // Unselect all
      setSelectedFixtures(new Set());
    } else {
      // Select all
      const allKeys = previewData.fixtures.map((f, index) => 
        `${f.homeTeam}-${f.awayTeam}-${f.date}-${index}`
      );
      setSelectedFixtures(new Set(allKeys));
    }
  };

  return (
