        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button>
          <Button onClick={handleSave} data-testid="btn-save-workitem">
            Update
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
