function TestCaseDialog({ 
  open, 
  onOpenChange, 
  onSave,
  onUpdate,
  existingTCs,
  frs,
  editTestCase
}: { 
  open: boolean; 
  onOpenChange: (open: boolean) => void;
  onSave: (data: { id: string; title: string; description?: string; steps?: string; expectedResult?: string; parentId?: string }) => void;
  onUpdate?: (id: string, data: { title: string; description?: string; steps?: string; expectedResult?: string; parentId?: string; status?: string }) => void;
  existingTCs: number;
  frs: { id: string; title: string }[];
  editTestCase?: TestCase | null;
}) {
  const isEditing = !!editTestCase;
  const [formData, setFormData] = useState({
    id: "",
    title: "",
    description: "",
    steps: "",
    expectedResult: "",
    actualResult: "",
    status: "new",
    parentId: "",
  });

  useEffect(() => {
    if (open) {
      if (editTestCase) {
        setFormData({
          id: editTestCase.id,
          title: editTestCase.title,
          description: editTestCase.objective || "",
          steps: editTestCase.steps.join('\n'),
          expectedResult: editTestCase.expectedResult || "",
          actualResult: editTestCase.actualResult || "",
          status: editTestCase.status || "new",
          parentId: "",
        });
      } else {
        const nextId = `TC-${String(existingTCs + 1).padStart(3, '0')}`;
        setFormData({
          id: nextId,
          title: "",
          description: "",
          steps: "",
          expectedResult: "",
          actualResult: "",
          status: "new",
          parentId: "",
        });
      }
    }
  }, [open, existingTCs, editTestCase]);

  const handleSave = () => {
    if (!formData.id || !formData.title) return;
    if (isEditing && onUpdate) {
      onUpdate(formData.id, {
        title: formData.title,
        description: formData.description || undefined,
        steps: formData.steps || undefined,
        expectedResult: formData.expectedResult || undefined,
        parentId: formData.parentId || undefined,
        status: formData.status,
      });
    } else {
      onSave({
        id: formData.id,
        title: formData.title,
        description: formData.description || undefined,
        steps: formData.steps || undefined,
        expectedResult: formData.expectedResult || undefined,
        parentId: formData.parentId || undefined,
      });
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[550px]">
        <DialogHeader>
          <DialogTitle>{isEditing ? 'Edit Test Case' : 'Add Test Case'}</DialogTitle>
          <DialogDescription>
            {isEditing ? 'Update test case details and status.' : 'Create a new test case. Link it to a functional requirement for traceability.'}
          </DialogDescription>
        </DialogHeader>
        <div className="grid gap-4 py-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="tc-id">TC ID</Label>
              <Input
                id="tc-id"
                value={formData.id}
                onChange={(e) => setFormData({ ...formData, id: e.target.value })}
                placeholder="e.g., TC-009"
                disabled={isEditing}
              />
            </div>
            {isEditing ? (
              <div className="space-y-2">
                <Label htmlFor="tc-status">Status</Label>
                <Select value={formData.status} onValueChange={(v) => setFormData({ ...formData, status: v })}>
                  <SelectTrigger id="tc-status">
                    <SelectValue placeholder="Select status" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="new">New</SelectItem>
                    <SelectItem value="passed">Passed</SelectItem>
                    <SelectItem value="failed">Failed</SelectItem>
                    <SelectItem value="partial">Partial</SelectItem>
                    <SelectItem value="blocked">Blocked</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            ) : (
              <div className="space-y-2">
                <Label htmlFor="tc-fr">Linked FR (optional)</Label>
                <Select value={formData.parentId || "none"} onValueChange={(v) => setFormData({ ...formData, parentId: v === "none" ? "" : v })}>
                  <SelectTrigger id="tc-fr">
                    <SelectValue placeholder="Select FR" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">None</SelectItem>
                    {frs.map(fr => (
                      <SelectItem key={fr.id} value={fr.id}>{fr.id} - {fr.title}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
          </div>
          <div className="space-y-2">
            <Label htmlFor="tc-title">Title</Label>
            <Input
              id="tc-title"
              value={formData.title}
              onChange={(e) => setFormData({ ...formData, title: e.target.value })}
              placeholder="e.g., Verify login with valid credentials"
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="tc-description">Description / Objective</Label>
            <Textarea
              id="tc-description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              placeholder="Brief description of what this test verifies..."
              rows={2}
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="tc-steps">Steps (one per line)</Label>
            <Textarea
              id="tc-steps"
              value={formData.steps}
              onChange={(e) => setFormData({ ...formData, steps: e.target.value })}
              placeholder="Navigate to login page&#10;Enter valid username&#10;Enter valid password&#10;Click login button"
              rows={4}
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="tc-expected">Expected Result</Label>
            <Textarea
              id="tc-expected"
              value={formData.expectedResult}
              onChange={(e) => setFormData({ ...formData, expectedResult: e.target.value })}
              placeholder="User is logged in and redirected to dashboard"
              rows={2}
            />
          </div>
          {isEditing && (
            <div className="space-y-2">
              <Label htmlFor="tc-actual">Actual Result</Label>
              <Textarea
                id="tc-actual"
                value={formData.actualResult}
                onChange={(e) => setFormData({ ...formData, actualResult: e.target.value })}
                placeholder="What actually happened during test execution..."
                rows={2}
              />
            </div>
          )}
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button>
          <Button onClick={handleSave} disabled={!formData.id || !formData.title}>
            {isEditing ? 'Save Changes' : 'Create TC'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

function TestRunDialog({ 
  open, 
  onOpenChange, 
  onSave,
  existingRuns
}: { 
  open: boolean; 
  onOpenChange: (open: boolean) => void;
  onSave: (data: { name: string; date?: string; testers?: string[]; buildInfo?: string; notes?: string }) => void;
  existingRuns: number;
}) {
  const [formData, setFormData] = useState({
    name: "",
    date: "",
    testers: "",
    buildInfo: "",
    notes: "",
  });

  useEffect(() => {
    if (open) {
      const today = new Date().toLocaleDateString('en-US', { month: '2-digit', day: '2-digit', year: 'numeric' }).replace(/\//g, '-');
      setFormData({
        name: `Test Run ${existingRuns + 1}`,
        date: today,
        testers: "",
        buildInfo: "",
        notes: "",
      });
    }
  }, [open, existingRuns]);

  const handleSave = () => {
    if (!formData.name) return;
    onSave({
      name: formData.name,
      date: formData.date || undefined,
      testers: formData.testers ? formData.testers.split(',').map(t => t.trim()) : undefined,
      buildInfo: formData.buildInfo || undefined,
      notes: formData.notes || undefined,
    });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[450px]">
        <DialogHeader>
          <DialogTitle>Add Test Run</DialogTitle>
          <DialogDescription>
            Create a new test run to track test execution results.
          </DialogDescription>
        </DialogHeader>
        <div className="grid gap-4 py-4">
          <div className="space-y-2">
            <Label htmlFor="tr-name">Name</Label>
            <Input
              id="tr-name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              placeholder="e.g., Sprint 5 Regression"
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="tr-date">Date</Label>
              <Input
                id="tr-date"
                value={formData.date}
                onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                placeholder="MM-DD-YYYY"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="tr-build">Build Info</Label>
              <Input
                id="tr-build"
                value={formData.buildInfo}
                onChange={(e) => setFormData({ ...formData, buildInfo: e.target.value })}
                placeholder="e.g., v1.2.0"
              />
            </div>
          </div>
          <div className="space-y-2">
            <Label htmlFor="tr-testers">Testers (comma-separated)</Label>
            <Input
              id="tr-testers"
              value={formData.testers}
              onChange={(e) => setFormData({ ...formData, testers: e.target.value })}
              placeholder="e.g., John, Jane, QA Team"
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="tr-notes">Notes</Label>
            <Textarea
              id="tr-notes"
              value={formData.notes}
              onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
              placeholder="Additional notes about this test run..."
              rows={2}
            />
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button>
          <Button onClick={handleSave} disabled={!formData.name}>
            Create Test Run
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

