  const handleSelectWorkItem = (item: WorkItem) => {
    // Handle page type items specially - find the PageRequirements and open the page sheet
    if (item.type === 'page') {
      const page = requirementsData.find(p => p.id === item.id);
      if (page) {
        handleSelectPage(page);
        return;
