    }
    // For all other work item types, find the full WorkItem from the data and open the dialog
    const fullWorkItem = workItems.find(w => w.id === item.id);
    if (fullWorkItem) {
      setSelectedWorkItem(fullWorkItem);
      setWorkItemDialogOpen(true);
    } else {
