  const handleSaveWorkItem = (data: Partial<WorkItem>) => {
    if (selectedWorkItem) {
      updateWorkItemMutation.mutate({ id: selectedWorkItem.id, data });
    }
  };

  const handleUpdateTestCase = (id: string, data: { title: string; description?: string; steps?: string; expectedResult?: string; status?: string; actualResult?: string }) => {
    // Convert steps string to array for jsonb storage
    const stepsArray = data.steps ? data.steps.split('\n').filter(s => s.trim()) : [];
    updateWorkItemMutation.mutate({
      id,
      data: {
        title: data.title,
        description: data.description,
        steps: stepsArray,
        expectedResult: data.expectedResult,
        actualResult: data.actualResult,
        status: data.status,
      }
    }, {
      onSuccess: () => {
        toast({ title: "Test case updated" });
        refetchWorkItems();
        setTestCaseDialogOpen(false);
        setEditingTestCase(null);
      }
    });
  };

  const handleEditTestCase = (tc: TestCase) => {
    setEditingTestCase(tc);
    setTestCaseDialogOpen(true);
  };

  const confirmDelete = () => {
    if (!itemToDelete) return;

    switch (itemToDelete.type) {
      case 'changelog':
        deleteChangeLogMutation.mutate(itemToDelete.item.id);
        break;
      case 'datamodel':
        deleteDataModelMutation.mutate(itemToDelete.item.id);
        break;
      case 'requirement':
        deleteRequirementMutation.mutate(itemToDelete.item.id);
        break;
      case 'widget':
        deleteWidgetMutation.mutate(itemToDelete.item.id);
        break;
