export type RequirementStatus = 'New' | 'Ready' | 'Coded' | 'Tested' | 'Complete';

export interface Requirement {
  id: string;
  description: string;
  status?: RequirementStatus;
  parentFrId?: string;
}

export interface FunctionalRequirement {
  id: string;
  title: string;
  description: string;
  status?: RequirementStatus;
}

export interface ChangeLogEntry {
  id: string;
  date: string;
  type: 'added' | 'removed' | 'changed' | 'fixed' | 'bug' | 'enhancement' | 'question' | 'action_item';
  area: string;
  description: string;
  priority?: 'low' | 'medium' | 'high' | 'critical';
  status?: 'open' | 'in_progress' | 'resolved' | 'closed';
}

export interface TestCase {
  id: string;
  title: string;
  objective: string;
  steps: string[];
  expectedResult: string;
  actualResult: string;
  status: 'passed' | 'failed' | 'partial' | 'blocked';
  associatedBug?: string;
  date: string;
  tester: string;
  component?: string;
}

export interface DataModelField {
  name: string;
  type: string;
  mandatory: boolean;
  defaultValue?: string;
  listOfValues?: string[];
  description?: string;
}

export interface DataModel {
  id: string;
  name: string;
  description: string;
  fields: DataModelField[];
}

export interface TabRequirements {
  id: string;
  name: string;
  overview: string;
  functionalRequirements: FunctionalRequirement[];
  acceptanceCriteria: Requirement[];
}

export interface EpicRequirements {
  id: string;
  title: string;
  route: string;
  overview: string;
  epicOverview?: string;
  parentId?: string;
  section: 'home' | 'team' | 'club' | 'devops' | 'global';
  displayOrder?: number;
  functionalRequirements: FunctionalRequirement[];
  acceptanceCriteria: Requirement[];
  tabs?: TabRequirements[];
}

// Backwards compatibility alias
export type PageRequirements = EpicRequirements;

